export const lessonMedia = {
  'abp-1-1': { video: { src: m1, poster: m2, title: "Preguntas que movilizan", duration: "1 min 37 s", objective: "Formular preguntas guía abiertas, relevantes y conectadas con el currículo.", reflection: "¿Qué tema de tu planificación podrías transformar en una pregunta guía?" }, guide: { label: "Guía: Preguntas que movilizan.pdf", href: m3 }, reading: {"type": "guide", "keyIdea": "Un proyecto empieza con una pregunta que vale la pena responder: abierta, relevante para el grupo y que obliga a aprender contenidos del currículo para contestarla.", "objectives": ["Reconocer las características de una buena pregunta guía.", "Transformar un tema en una pregunta abierta.", "Conectar la pregunta con contenidos curriculares."], "sections": [{"title": "La idea central", "text": "Una buena pregunta guía es abierta, relevante y obliga a usar contenidos del currículo. La pregunta sostiene todo el proyecto: vale la pena pensarla bien."}, {"title": "Rasgos de una buena pregunta", "items": ["Abierta: No se responde con un dato ni con sí o no: admite varias respuestas.", "Relevante: Se conecta con algo que le importa al grupo o a la comunidad.", "Curricular: Para responderla, hay que aprender contenidos del programa."]}, {"title": "En el aula", "text": "Un quinto grado arranca su proyecto con la pregunta: ¿cómo podemos reducir el desperdicio de agua en la escuela? Para responderla, miden cuánta agua se pierde, calculan litros y porcentajes y estudian el ciclo del agua. La pregunta articula ciencias, matemática y comunicación en un mismo recorrido."}, {"title": "Paso a paso", "items": ["Elegí los contenidos que el proyecto tiene que abordar.", "Buscá una situación real donde esos contenidos importen.", "Escribí la pregunta empezando por «¿Cómo podemos…?».", "Probala con colegas: ¿es abierta, relevante y curricular?"]}, {"title": "Cuidado con…", "items": ["Formular una pregunta que se responde buscando en internet.", "Elegir una pregunta interesante que no lleva a los contenidos.", "Plantear una pregunta tan amplia que no se puede abordar."]}], "practice": "Del tema a la pregunta: Practicar la formulación de preguntas guía a partir de temas curriculares. La consigna completa está en la guía de la lección."} },
  'abp-1-2': { video: { src: m4, poster: m5, title: "Producto y destinatario", duration: "1 min 34 s", objective: "Definir un producto auténtico y un destinatario real para dar sentido al proyecto.", reflection: "¿Quién podría ser el destinatario real de un proyecto de tu área?" }, guide: { label: "Guía: Producto y destinatario real.pdf", href: m6 }, reading: {"type": "guide", "keyIdea": "Cuando el proyecto produce algo útil para alguien real, como una campaña, un informe o una propuesta, la investigación cobra sentido y la calidad importa de verdad.", "objectives": ["Elegir productos auténticos.", "Identificar destinatarios reales.", "Acotar el alcance para que el proyecto sea viable."], "sections": [{"title": "La idea central", "text": "Un producto auténtico responde a una necesidad real y tiene un destinatario fuera del aula. Saber para quién se trabaja cambia la forma de trabajar."}, {"title": "Cómo definirlo", "items": ["Producto: Algo concreto: un folleto, un video, una maqueta, una propuesta escrita.", "Destinatario: Las familias, otro curso, la cooperadora, un organismo del barrio.", "Alcance: Que se pueda hacer con el tiempo y los recursos disponibles."]}, {"title": "En el aula", "text": "El grupo decide que su producto será un folleto con recomendaciones para ahorrar agua. El destinatario: las familias de la escuela, que lo van a recibir en la reunión de padres. Saber que lo van a leer sus familias hace que revisen datos y cuiden la redacción."}, {"title": "Paso a paso", "items": ["Pensá qué producto respondería a la pregunta guía.", "Elegí un destinatario real y alcanzable.", "Acotá el producto para que entre en el tiempo disponible.", "Contale al grupo desde el inicio para quién trabajan."]}, {"title": "Cuidado con…", "items": ["Elegir un producto que solo decora el cierre.", "Inventar un destinatario que nunca va a recibir el trabajo.", "Proponer un producto tan grande que no se termina."]}], "practice": "Lluvia de destinatarios: Que el grupo elija para quién producir y qué producto sería útil. La consigna completa está en la guía de la lección."} },
  'abp-2-1': { video: { src: m7, poster: m8, title: "Organizar la investigación", duration: "1 min 34 s", objective: "Planificar fuentes, tareas y registros para construir información confiable.", reflection: "¿Qué fuente distinta de internet podrían usar tus estudiantes en una investigación?" }, guide: { label: "Guía: Organizar la investigación.pdf", href: m9 }, reading: {"type": "guide", "keyIdea": "Investigar en un proyecto no es buscar en internet y copiar: es planificar qué fuentes consultar, quién hace qué y cómo se registra la información, para que el grupo construya respuestas confiables.", "objectives": ["Planificar fuentes variadas y confiables.", "Distribuir tareas con roles claros.", "Registrar la información y sus fuentes."], "sections": [{"title": "La idea central", "text": "Una buena investigación planifica fuentes, tareas y registros. Organizar la investigación es enseñar a investigar."}, {"title": "Tres decisiones clave", "items": ["Fuentes variadas: Libros, entrevistas, mediciones propias, sitios confiables.", "Roles: Quién busca, quién entrevista, quién registra, quién revisa.", "Registro: Una tabla con el dato, la fuente y para qué sirve."]}, {"title": "En el aula", "text": "Para investigar la historia del barrio, cada grupo tiene una tabla con tres columnas: dato, fuente y relación con la pregunta. Un integrante entrevista a vecinos, otro consulta el archivo de la biblioteca y otro saca fotos. Antes de escribir, comparan los datos de las distintas fuentes."}, {"title": "Paso a paso", "items": ["Definí con el grupo qué necesitan averiguar.", "Listá fuentes posibles, más allá de internet.", "Asigná roles rotativos dentro de cada grupo.", "Usá una tabla para registrar datos y fuentes."]}, {"title": "Cuidado con…", "items": ["Dejar la búsqueda librada a internet sin criterios.", "Repartir partes del trabajo sin que se integren.", "No registrar de dónde sale cada dato."]}], "practice": "Tabla de fuentes: Organizar la búsqueda de información registrando datos y fuentes. La consigna completa está en la guía de la lección."} },
  'abp-2-2': { video: { src: m10, poster: m11, title: "Prototipos y revisión", duration: "1 min 32 s", objective: "Usar versiones tempranas para recibir devoluciones antes del producto final.", reflection: "¿En qué momento de un proyecto tuyo podrías sumar una prueba con otro grupo?" }, guide: { label: "Guía: Prototipos y revisión.pdf", href: m12 }, reading: {"type": "guide", "keyIdea": "Un prototipo es una primera versión que se muestra antes de terminar, para recibir comentarios y mejorar. Probar temprano evita llegar al final con un producto que no funciona.", "objectives": ["Comprender para qué sirve un prototipo.", "Organizar instancias de devolución.", "Mejorar el producto a partir de lo recibido."], "sections": [{"title": "La idea central", "text": "Un prototipo es una versión temprana para probar, recibir devoluciones y mejorar. Equivocarse en el prototipo es parte del proceso; equivocarse en el final, no."}, {"title": "El ciclo del prototipo", "items": ["Hacer una versión simple: Un boceto, un borrador, una maqueta de cartón.", "Mostrarla: A otro grupo o a alguien del destinatario, con preguntas concretas.", "Mejorar: Elegir qué cambios hacer y producir una nueva versión."]}, {"title": "En el aula", "text": "Antes de imprimir el folleto, el grupo muestra un borrador a sexto grado. Les preguntan: ¿qué entendiste? ¿Qué no se entiende? ¿Qué harías en tu casa? A partir de las respuestas, simplifican el texto y agregan dibujos."}, {"title": "Paso a paso", "items": ["Pedí una primera versión simple a mitad del proyecto.", "Prepará con el grupo preguntas para quienes la prueben.", "Organizá la prueba con otro grupo o con el destinatario.", "Dejá tiempo para hacer los cambios."]}, {"title": "Cuidado con…", "items": ["Pedir que el prototipo esté «lindo» desde el principio.", "Recibir devoluciones sin tiempo para mejorar.", "Preguntar «¿te gustó?» en lugar de preguntas concretas."]}], "practice": "Feria de prototipos: Probar versiones tempranas y recibir devoluciones concretas. La consigna completa está en la guía de la lección."} },
  'abp-3-1': { video: { src: m13, poster: m14, title: "Comunicar hallazgos", duration: "1 min 28 s", objective: "Seleccionar evidencias y adaptar el mensaje al destinatario.", reflection: "¿Qué tres evidencias elegiría tu grupo para presentar su último trabajo?" }, guide: { label: "Guía: Comunicar hallazgos.pdf", href: m15 }, reading: {"type": "guide", "keyIdea": "Comunicar no es mostrar todo lo que se hizo: es elegir las evidencias más importantes y adaptarlas a quien escucha, para que la respuesta a la pregunta guía se entienda y convenza.", "objectives": ["Seleccionar las evidencias principales.", "Adaptar el mensaje al destinatario.", "Organizar una presentación clara."], "sections": [{"title": "La idea central", "text": "Comunicar es seleccionar evidencias y adaptar el mensaje a quien lo recibe. Menos es más: tres buenas evidencias convencen más que veinte datos sueltos."}, {"title": "Cómo comunicar", "items": ["Seleccionar: Elegir las tres evidencias que mejor responden la pregunta.", "Adaptar: Pensar qué sabe y qué necesita el destinatario.", "Ordenar: Problema, lo que encontramos, lo que proponemos."]}, {"title": "En el aula", "text": "El curso presenta su proyecto sobre basura en la plaza ante el centro vecinal. En lugar de leer todo el informe, muestran tres datos: cuánta basura juntaron, dónde se acumula y qué tipo es. Cierran con una propuesta concreta: dos cestos y un cartel diseñado por ellos."}, {"title": "Paso a paso", "items": ["Volvé con el grupo a la pregunta guía.", "Elijan las tres evidencias que mejor la responden.", "Piensen qué necesita saber el destinatario.", "Ensayen la presentación con otro grupo."]}, {"title": "Cuidado con…", "items": ["Incluir toda la información reunida.", "Usar el mismo formato para cualquier público.", "Leer textos largos durante la presentación."]}], "practice": "Tres evidencias: Practicar la selección de evidencias para comunicar un hallazgo. La consigna completa está en la guía de la lección."} },
  'abp-3-2': { video: { src: m16, poster: m17, title: "Evaluar producto y proceso", duration: "1 min 32 s", objective: "Evaluar la calidad del producto, el uso de conocimientos, la colaboración y la revisión.", reflection: "¿Qué criterio de proceso podrías sumar a la evaluación de tu próximo proyecto?" }, guide: { label: "Guía: Evaluar producto y proceso.pdf", href: m18 }, reading: {"type": "guide", "keyIdea": "En un proyecto se evalúa el producto, pero también el proceso: cómo se usaron los conocimientos, cómo se colaboró y cómo se mejoró. Los criterios se comparten desde el inicio.", "objectives": ["Definir criterios para el producto y el proceso.", "Compartir los criterios desde el inicio.", "Incluir autoevaluación y reflexión final."], "sections": [{"title": "La idea central", "text": "Un proyecto se evalúa por su producto y por su proceso, con criterios anticipados. Si los criterios se conocen desde el inicio, orientan todo el trabajo."}, {"title": "Qué evaluar", "items": ["El producto: ¿Responde la pregunta? ¿Usa bien los contenidos? ¿Sirve al destinatario?", "El proceso: ¿Cómo colaboró el grupo? ¿Usaron las devoluciones para mejorar?", "La reflexión: ¿Qué aprendí? ¿Qué decisiones tomamos? ¿Qué haría distinto?"]}, {"title": "En el aula", "text": "Al comenzar, el profesor entrega una rúbrica con criterios para el producto y para el trabajo en equipo. A mitad del proyecto, cada grupo se autoevalúa con la rúbrica y define una mejora. Al final, cada estudiante escribe una reflexión sobre lo que aprendió y su aporte al grupo."}, {"title": "Paso a paso", "items": ["Definí criterios para el producto y para el proceso.", "Compartilos al iniciar, con ejemplos.", "Hacé una autoevaluación a mitad del proyecto.", "Cerrá con una reflexión individual."]}, {"title": "Cuidado con…", "items": ["Evaluar solo la presentación oral.", "Definir los criterios después de la entrega.", "Poner la misma nota a todo el grupo sin mirar aportes individuales."]}], "practice": "Rúbrica de proyecto: Construir criterios para evaluar el producto y el proceso de un proyecto. La consigna completa está en la guía de la lección."} },
  'ai-1-1': { video: { src: m19, poster: m20, title: "Seleccionar lo esencial", duration: "1 min 35 s", objective: "Preparar un trabajo previo breve, centrado en una idea que luego se usará en clase.", reflection: "¿Qué parte de tu próximo tema podría verse antes de la clase?" }, guide: { label: "Guía: Seleccionar lo esencial.pdf", href: m21 }, reading: {"type": "guide", "keyIdea": "En el aula invertida, los estudiantes se acercan a una idea antes de la clase, y el encuentro se usa para aplicarla. El trabajo previo funciona si es breve, está acotado a lo esencial y tiene una consigna clara.", "objectives": ["Comprender la lógica del aula invertida.", "Seleccionar una idea esencial para el trabajo previo.", "Diseñar una consigna que oriente qué mirar."], "sections": [{"title": "La idea central", "text": "El trabajo previo presenta una idea acotada que después se usa activamente en clase. Si el material previo es largo, pocos lo van a ver; si es corto y claro, la clase arranca con ventaja."}, {"title": "Un buen trabajo previo", "items": ["Breve: Un video de cinco minutos o un texto de una página, no una clase entera grabada.", "Una idea esencial: Lo justo para poder trabajar en clase, no todo el tema.", "Con una consigna: Qué observar, qué anotar o qué pregunta traer al encuentro."]}, {"title": "En el aula", "text": "Antes de la clase de mezclas, el profesor comparte un video de cuatro minutos. La consigna: anotá dos ejemplos de mezclas de tu casa y una duda. En clase, el grupo usa esos ejemplos para clasificar mezclas y diseñar cómo separarlas."}, {"title": "Paso a paso", "items": ["Elegí qué parte del tema es esencial para la clase.", "Buscá o grabá un material de pocos minutos.", "Escribí una consigna de lo que tienen que traer.", "Planificá cómo vas a usar en clase lo que traigan."]}, {"title": "Cuidado con…", "items": ["Grabar una clase completa de cuarenta minutos.", "Mandar material sin consigna.", "Repetir en clase la misma explicación del video."]}], "practice": "Mi primer material previo: Diseñar un trabajo previo breve con una consigna clara. La consigna completa está en la guía de la lección."} },
  'ai-1-2': { video: { src: m22, poster: m23, title: "Acceso y comprensión", duration: "1 min 36 s", objective: "Garantizar que todos puedan acceder al material previo y comprenderlo.", reflection: "¿Qué alternativa sin conexión podrías ofrecer para tu próximo material previo?" }, guide: { label: "Guía: Asegurar acceso y comprensión.pdf", href: m24 }, reading: {"type": "guide", "keyIdea": "Si el trabajo previo depende de tener conexión en casa, deja afuera a una parte del grupo. Hace falta ofrecer formatos accesibles, instrucciones claras y una alternativa sin conexión.", "objectives": ["Anticipar barreras de acceso al material previo.", "Ofrecer alternativas equivalentes.", "Escribir instrucciones claras y breves."], "sections": [{"title": "La idea central", "text": "El material previo tiene que ser accesible para todos, con o sin conexión. Una alternativa equivalente no es un castigo: es otra puerta al mismo contenido."}, {"title": "Cómo asegurar el acceso", "items": ["Liviano y descargable: Videos cortos y livianos, que se puedan bajar en la escuela o compartir por mensaje.", "Alternativa impresa: Una ficha en papel con el mismo contenido esencial.", "Tiempo en la escuela: Un espacio en la biblioteca o al inicio de la clase para quien no pudo verlo."]}, {"title": "En el aula", "text": "La docente comparte un video de tres minutos por el grupo de mensajes de las familias. Además, imprime una ficha con las mismas ideas y algunas imágenes. Quien no pudo ver ni leer nada, tiene diez minutos al inicio de la clase con la ficha."}, {"title": "Paso a paso", "items": ["Preguntá al grupo con qué conectividad y dispositivos cuentan.", "Elegí formatos livianos.", "Prepará una alternativa impresa equivalente.", "Planificá un tiempo de puesta al día al inicio."]}, {"title": "Cuidado con…", "items": ["Suponer que todos tienen conexión en casa.", "Penalizar a quien no hizo el trabajo previo.", "Usar plataformas que piden muchos datos o cuentas."]}], "practice": "Relevamiento de acceso: Conocer las condiciones reales de acceso del grupo antes de diseñar el trabajo previo. La consigna completa está en la guía de la lección."} },
  'ai-2-1': { video: { src: m25, poster: m26, title: "Actividades de aplicación", duration: "1 min 29 s", objective: "Usar el tiempo de clase para resolver, debatir y producir con acompañamiento.", reflection: "¿Qué situación nueva podría poner a prueba la idea de tu próximo trabajo previo?" }, guide: { label: "Guía: Actividades de aplicación.pdf", href: m27 }, reading: {"type": "guide", "keyIdea": "El valor del aula invertida está en lo que pasa en el encuentro: el tiempo se usa para aplicar la idea en situaciones nuevas, con el docente cerca para acompañar.", "objectives": ["Diseñar actividades de aplicación para la clase.", "Proponer situaciones nuevas, no repeticiones.", "Organizar el tiempo de clase para acompañar."], "sections": [{"title": "La idea central", "text": "En clase, la idea se usa en situaciones nuevas, con acompañamiento docente. El docente deja de ser quien explica todo y pasa a ser quien acompaña el trabajo."}, {"title": "Tipos de actividades", "items": ["Resolver: Problemas o casos donde hay que usar la idea vista.", "Debatir: Discutir una situación con argumentos basados en lo aprendido.", "Producir: Crear algo: un esquema, un texto, una explicación para otros."]}, {"title": "En el aula", "text": "Con los ejemplos de mezclas que trajeron, los grupos reciben un desafío. Tienen que separar una mezcla de arena, sal y agua con materiales simples, y explicar cada paso. El profesor recorre los grupos, hace preguntas y ayuda a quien se traba."}, {"title": "Paso a paso", "items": ["Empezá retomando lo que trajeron del trabajo previo.", "Proponé una situación nueva donde usar la idea.", "Organizá grupos y recorré el aula acompañando.", "Cerrá con una puesta en común de soluciones."]}, {"title": "Cuidado con…", "items": ["Volver a explicar todo en clase.", "Proponer ejercicios idénticos a los del material.", "Quedarse en el escritorio mientras los grupos trabajan."]}], "practice": "Caso para resolver: Aplicar en clase una idea vista en el trabajo previo. La consigna completa está en la guía de la lección."} },
  'ai-2-2': { video: { src: m28, poster: m29, title: "Acompañamiento diferenciado", duration: "1 min 28 s", objective: "Observar durante la actividad para ofrecer apoyos y desafíos según las evidencias.", reflection: "¿Qué apoyo y qué desafío podrías tener preparados para tu próxima clase?" }, guide: { label: "Guía: Acompañamiento diferenciado.pdf", href: m30 }, reading: {"type": "guide", "keyIdea": "Mientras el grupo trabaja, el docente puede observar quién avanza, quién se traba y por qué. Esa información permite ofrecer apoyos a quien los necesita y desafíos a quien está listo para más.", "objectives": ["Observar evidencias durante el trabajo en clase.", "Ofrecer apoyos según la dificultad observada.", "Preparar desafíos para quien avanza."], "sections": [{"title": "La idea central", "text": "Observar el trabajo en clase permite dar a cada uno el apoyo o el desafío que necesita. El apoyo responde a una dificultad observable, no a una etiqueta."}, {"title": "Cómo acompañar", "items": ["Observar: Recorrer los grupos y anotar quién avanza y dónde se traban.", "Apoyar: Una pregunta, una pista o un ejemplo para quien se traba.", "Desafiar: Una variante más compleja para quien ya resolvió."]}, {"title": "En el aula", "text": "Mientras los grupos resuelven problemas de proporcionalidad, la docente recorre con una planilla. Anota que un grupo confunde sumar con multiplicar y se sienta con ellos con un ejemplo concreto. Al grupo que terminó le da una variante con números más grandes."}, {"title": "Paso a paso", "items": ["Prepará una planilla simple para anotar observaciones.", "Recorré todos los grupos al menos una vez.", "Tené listos apoyos y desafíos.", "Usá las observaciones para planificar la próxima clase."]}, {"title": "Cuidado con…", "items": ["Atender solo a quien levanta la mano.", "Dar la respuesta en lugar de una pista.", "No registrar lo observado."]}], "practice": "Planilla de recorrido: Registrar observaciones para acompañar de forma diferenciada. La consigna completa está en la guía de la lección."} },
  'ai-3-1': { video: { src: m31, poster: m32, title: "Recuperar evidencias previas", duration: "1 min 30 s", objective: "Usar una pregunta breve sobre el trabajo previo para planificar el encuentro.", reflection: "¿Qué pregunta podría mostrarte si tu grupo entendió el material previo?" }, guide: { label: "Guía: Recuperar evidencias previas.pdf", href: m33 }, reading: {"type": "guide", "keyIdea": "Antes del encuentro, una pregunta corta sobre el material previo muestra qué comprendió el grupo. Con esa información, el docente decide cómo empezar la clase.", "objectives": ["Diseñar preguntas breves sobre el trabajo previo.", "Analizar las respuestas antes de la clase.", "Ajustar el inicio del encuentro."], "sections": [{"title": "La idea central", "text": "Una pregunta breve sobre el trabajo previo informa cómo organizar el encuentro. No hace falta una prueba: con una o dos preguntas alcanza para decidir."}, {"title": "Cómo recuperar evidencias", "items": ["Una pregunta clave: Sobre la idea esencial, no sobre detalles.", "Una vía simple: Un formulario, un mensaje o un papel al entrar.", "Una decisión: Si la mayoría entendió, avanzar; si no, empezar retomando."]}, {"title": "En el aula", "text": "Después de un video sobre la Revolución de Mayo, cada estudiante responde una pregunta en un formulario. ¿Por qué crees que se formó la Primera Junta? Respondé en dos líneas. El profesor ve muchas respuestas confusas y decide empezar la clase con una línea de tiempo entre todos."}, {"title": "Paso a paso", "items": ["Escribí una pregunta sobre la idea esencial.", "Elegí una vía simple para recibir respuestas.", "Leé las respuestas antes de la clase.", "Decidí cómo empezar según lo que encontraste."]}, {"title": "Cuidado con…", "items": ["Hacer muchas preguntas que nadie tiene tiempo de analizar.", "Preguntar detalles en lugar de la idea central.", "Recoger respuestas y no cambiar nada."]}], "practice": "Pregunta de entrada: Recoger evidencia sobre el trabajo previo para decidir cómo empezar. La consigna completa está en la guía de la lección."} },
  'ai-3-2': { video: { src: m34, poster: m35, title: "Evaluar el diseño invertido", duration: "1 min 30 s", objective: "Mejorar la propuesta analizando acceso, participación y aprendizaje.", reflection: "¿Qué preguntarías a tu grupo para mejorar una propuesta de aula invertida?" }, guide: { label: "Guía: Evaluar el diseño invertido.pdf", href: m36 }, reading: {"type": "guide", "keyIdea": "Para saber si el aula invertida funciona, no alcanza con contar cuántos vieron el video. Hay que mirar si todos pudieron acceder, si participaron en clase y si aprendieron.", "objectives": ["Definir indicadores para evaluar la propuesta.", "Recoger la opinión del grupo.", "Ajustar materiales y actividades."], "sections": [{"title": "La idea central", "text": "Una propuesta invertida se evalúa por acceso, participación y aprendizaje. Mirar solo las visualizaciones es mirar lo menos importante."}, {"title": "Qué mirar", "items": ["Acceso: ¿Pudieron todos llegar al material, en distintas condiciones?", "Participación: ¿Cómo trabajaron en clase quienes hicieron y quienes no hicieron el trabajo previo?", "Aprendizaje: ¿Qué muestran las producciones al final de la secuencia?"]}, {"title": "En el aula", "text": "Después de un mes de aula invertida, la profesora hace una encuesta anónima de tres preguntas. Descubre que los videos eran largos y que varios no podían verlos con datos móviles. Los acorta a la mitad y suma una ficha impresa: en el mes siguiente, más estudiantes llegan preparados."}, {"title": "Paso a paso", "items": ["Definí qué vas a mirar: acceso, participación y aprendizaje.", "Preguntale al grupo cómo le resultó.", "Compará producciones antes y después.", "Ajustá materiales y actividades."]}, {"title": "Cuidado con…", "items": ["Medir el éxito solo por las visualizaciones.", "No preguntar al grupo cómo le resultó.", "Mantener la propuesta igual aunque no funcione."]}], "practice": "Encuesta de tres preguntas: Conocer cómo vivió el grupo la propuesta para mejorarla. La consigna completa está en la guía de la lección."} },
  'dr-1-1': { video: { src: m37, poster: m38, title: "Del objetivo al criterio", duration: "1 min 29 s", objective: "Derivar criterios de evaluación a partir de los objetivos de aprendizaje.", reflection: "¿Qué criterio de alguna rúbrica tuya no sale realmente del objetivo?" }, guide: { label: "Guía: Del objetivo al criterio.pdf", href: m39 }, reading: {"type": "guide", "keyIdea": "Una rúbrica empieza por los criterios, y los criterios salen del objetivo: describen qué rasgos del desempeño muestran que se aprendió. Si el criterio no se relaciona con el objetivo, la rúbrica evalúa otra cosa.", "objectives": ["Reconocer qué es un criterio de evaluación.", "Derivar criterios a partir de un objetivo.", "Revisar la alineación entre objetivo, tarea y criterios."], "sections": [{"title": "La idea central", "text": "Un criterio describe qué rasgo del desempeño muestra el aprendizaje esperado. Si el criterio no está en el objetivo, preguntate por qué lo estás evaluando."}, {"title": "Del objetivo al criterio", "items": ["Objetivo: Argumentar una opinión sobre un tema de actualidad.", "Criterios: Postura clara, argumentos con fundamento, uso de conectores.", "Tarea: Una carta de lectores para el diario local."]}, {"title": "En el aula", "text": "La profesora quiere evaluar cartas de lectores. Su primera rúbrica tenía «prolijidad» y «extensión», que no estaban en el objetivo. La reescribe con tres criterios que sí lo están: postura, argumentos y organización del texto."}, {"title": "Paso a paso", "items": ["Escribí el objetivo de la tarea.", "Preguntate: ¿qué se ve en un trabajo que logró este objetivo?", "Convertí cada respuesta en un criterio.", "Quitá los criterios que no salen del objetivo."]}, {"title": "Cuidado con…", "items": ["Incluir criterios que no se enseñaron.", "Mezclar en un criterio varias cosas distintas.", "Tener tantos criterios que la rúbrica se vuelve inmanejable."]}], "practice": "Auditoría de criterios: Revisar una rúbrica propia para verificar que los criterios salen del objetivo. La consigna completa está en la guía de la lección."} },
  'dr-1-2': { video: { src: m40, poster: m41, title: "Criterios claros y compartidos", duration: "1 min 30 s", objective: "Redactar criterios con lenguaje concreto que estudiantes y docentes interpreten igual.", reflection: "¿Qué palabra vaga aparece en tus criterios y cómo podrías concretarla?" }, guide: { label: "Guía: Criterios claros y compartidos.pdf", href: m42 }, reading: {"type": "guide", "keyIdea": "Un criterio claro usa palabras que todos entienden de la misma forma: acciones y rasgos concretos, no adjetivos vagos. Así, estudiantes y docentes pueden usar la rúbrica para mirar el mismo trabajo.", "objectives": ["Reconocer criterios vagos y criterios claros.", "Redactar criterios con lenguaje concreto.", "Compartir los criterios con ejemplos."], "sections": [{"title": "La idea central", "text": "Un criterio claro nombra acciones y rasgos concretos que se pueden ver en el trabajo. Si dos docentes evalúan el mismo trabajo y no coinciden, el criterio no es claro."}, {"title": "De vago a claro", "items": ["Vago: «Buena presentación», «creativo», «completo».", "Claro: «Incluye título, fuentes y conclusión», «propone una solución distinta a las vistas».", "Con ejemplo: Mostrar un trabajo que cumple el criterio y uno que no."]}, {"title": "En el aula", "text": "La docente cambia el criterio «informe completo» por «nombra el problema, describe lo que observó y explica qué aprendió». Muestra un informe de otro año que lo cumple. Los chicos usan esa misma frase para revisar sus informes antes de entregarlos."}, {"title": "Paso a paso", "items": ["Subrayá los adjetivos vagos de tus criterios.", "Reemplazalos por acciones o rasgos observables.", "Probá el criterio con un colega: ¿evalúan igual?", "Mostralo al grupo con un ejemplo."]}, {"title": "Cuidado con…", "items": ["Usar palabras que solo entiende el docente.", "Escribir criterios largos y difíciles de leer.", "Compartir la rúbrica recién al devolver la nota."]}], "practice": "Traducir criterios: Que los estudiantes comprendan los criterios reescribiéndolos con sus palabras. La consigna completa está en la guía de la lección."} },
  'dr-2-1': { video: { src: m43, poster: m44, title: "Descriptores progresivos", duration: "1 min 32 s", objective: "Escribir niveles de desempeño que muestren diferencias de calidad, no solo cantidad.", reflection: "¿Qué criterio de tus rúbricas usa conteo en lugar de calidad?" }, guide: { label: "Guía: Descriptores progresivos.pdf", href: m45 }, reading: {"type": "guide", "keyIdea": "Los niveles de una rúbrica describen cómo se ve cada criterio en distintos grados de logro. Un buen descriptor muestra una diferencia de calidad, en lugar de contar errores o usar «poco, algo, mucho».", "objectives": ["Distinguir descriptores cualitativos y cuantitativos.", "Escribir niveles que muestren progresión.", "Usar el nivel logrado como punto de partida."], "sections": [{"title": "La idea central", "text": "Un descriptor progresivo muestra cómo cambia la calidad de un desempeño de un nivel a otro. Un buen descriptor le dice al estudiante qué tiene que hacer para pasar al nivel siguiente."}, {"title": "Cómo escribir los niveles", "items": ["Empezar por el logrado: Describir primero cómo se ve el desempeño esperado.", "Mostrar el camino: Describir qué falta en los niveles anteriores, en términos de calidad.", "Evitar el conteo: No usar solo «pocos o muchos errores» ni «siempre, a veces, nunca»."]}, {"title": "En el aula", "text": "Para el criterio «usa fuentes», la rúbrica describe tres niveles. En proceso: menciona una fuente sin relacionarla. Logrado: usa dos fuentes y explica qué aporta cada una. Destacado: compara fuentes y señala diferencias entre ellas."}, {"title": "Paso a paso", "items": ["Escribí primero el nivel logrado.", "Pensá qué le falta al nivel anterior para llegar.", "Describí qué agrega el nivel destacado.", "Leé los niveles en orden: ¿se ve una progresión?"]}, {"title": "Cuidado con…", "items": ["Repetir el mismo texto cambiando solo «poco» por «mucho».", "Escribir niveles que no se distinguen entre sí.", "Describir solo lo que falta, sin decir qué se logra."]}], "practice": "Escalera de niveles: Practicar la escritura de descriptores progresivos. La consigna completa está en la guía de la lección."} },
  'dr-2-2': { video: { src: m46, poster: m47, title: "Evitar sesgos", duration: "1 min 30 s", objective: "Revisar los descriptores para que valoren el aprendizaje y no condiciones ajenas a él.", reflection: "¿Qué criterio de tus rúbricas podría favorecer a quien tiene más recursos?" }, guide: { label: "Guía: Evitar sesgos en la rúbrica.pdf", href: m48 }, reading: {"type": "guide", "keyIdea": "Una rúbrica tiene sesgos cuando premia cosas ajenas al aprendizaje: tener impresora, buena letra, materiales caros o ayuda en casa. Revisar los descriptores con esa mirada hace la evaluación más justa.", "objectives": ["Reconocer sesgos frecuentes en las rúbricas.", "Revisar los descriptores con criterios de equidad.", "Reformular criterios para centrarlos en el aprendizaje."], "sections": [{"title": "La idea central", "text": "Una rúbrica justa valora el aprendizaje, no los recursos ni las condiciones de cada familia. Lo que no se enseñó en la escuela no debería pesar en la nota."}, {"title": "Sesgos frecuentes", "items": ["Recursos: Premiar impresiones a color, materiales caros o tecnología en casa.", "Forma: Valorar la letra o la prolijidad cuando el objetivo es otro.", "Ayuda externa: Tareas que dependen de que alguien en casa pueda ayudar."]}, {"title": "En el aula", "text": "La rúbrica de una maqueta tenía el criterio «materiales vistosos». La docente lo reemplaza por «representa los elementos del paisaje y los explica». Además, propone hacer la maqueta en la escuela con materiales reciclados."}, {"title": "Paso a paso", "items": ["Leé cada criterio y preguntá: ¿mide aprendizaje?", "Preguntá: ¿alguien podría sacar menos por sus condiciones?", "Reformulá los criterios con sesgo.", "Si la tarea depende de recursos, hacela en la escuela."]}, {"title": "Cuidado con…", "items": ["Dar puntos por «presentación» sin definir qué es.", "Evaluar tareas hechas en casa como si todos tuvieran las mismas condiciones.", "No revisar la rúbrica después de usarla."]}], "practice": "Lupa de equidad: Revisar una rúbrica con criterios de equidad. La consigna completa está en la guía de la lección."} },
  'dr-3-1': { video: { src: m49, poster: m50, title: "Autoevaluar con evidencias", duration: "1 min 28 s", objective: "Usar la rúbrica para que los estudiantes revisen su trabajo justificando con evidencias.", reflection: "¿En qué entrega podrías sumar una autoevaluación con evidencias?" }, guide: { label: "Guía: Autoevaluar con evidencias.pdf", href: m51 }, reading: {"type": "guide", "keyIdea": "La rúbrica sirve también a los estudiantes: pueden ubicar su trabajo en un nivel, siempre que justifiquen con evidencias concretas de su producción. Así aprenden a mirar su trabajo con criterios.", "objectives": ["Proponer autoevaluaciones con la rúbrica.", "Pedir evidencias que justifiquen el nivel elegido.", "Usar la autoevaluación para planificar mejoras."], "sections": [{"title": "La idea central", "text": "Autoevaluar es elegir un nivel y justificarlo con evidencias del propio trabajo. La autoevaluación vale por la justificación, no por el número."}, {"title": "Cómo hacerlo", "items": ["Ubicar: El estudiante elige el nivel que cree que alcanzó en cada criterio.", "Señalar: Marca en su trabajo dónde se ve ese nivel.", "Planificar: Escribe qué tendría que hacer para llegar al nivel siguiente."]}, {"title": "En el aula", "text": "Antes de entregar el ensayo, cada estudiante resalta con colores dónde aparece su postura y sus argumentos. Elige un nivel para cada criterio y escribe una frase que lo justifique. Después elige un criterio para mejorar y lo trabaja en clase."}, {"title": "Paso a paso", "items": ["Repasá la rúbrica con el grupo antes de autoevaluar.", "Pedí que marquen en el trabajo las evidencias.", "Pedí una frase de justificación por criterio.", "Cerrá con una mejora elegida por cada uno."]}, {"title": "Cuidado con…", "items": ["Pedir un número sin justificación.", "Usar la autoevaluación como nota final.", "No dejar tiempo para mejorar después."]}], "practice": "Semáforo con evidencias: Autoevaluar una producción con la rúbrica, justificando con evidencias. La consigna completa está en la guía de la lección."} },
  'dr-3-2': { video: { src: m52, poster: m53, title: "Retroalimentar y revisar", duration: "1 min 33 s", objective: "Usar la rúbrica para dar devoluciones que prioricen una mejora y habiliten una nueva versión.", reflection: "¿Qué tarea tuya podría tener una segunda versión después de la devolución?" }, guide: { label: "Guía: Retroalimentar y revisar.pdf", href: m54 }, reading: {"type": "guide", "keyIdea": "La rúbrica permite dar devoluciones precisas: señalar en qué nivel está el trabajo en un criterio y qué haría falta para avanzar. La devolución tiene más valor si hay una oportunidad de hacer una nueva versión.", "objectives": ["Dar devoluciones basadas en criterios.", "Priorizar una mejora por vez.", "Organizar instancias de revisión."], "sections": [{"title": "La idea central", "text": "Una devolución con rúbrica señala un criterio, propone un próximo paso y habilita una nueva versión. Priorizar una mejora es más útil que señalar todo lo que falta."}, {"title": "Del nivel a la mejora", "items": ["Elegir un criterio: El que más impacto tendría en la calidad del trabajo.", "Nombrar el próximo nivel: Usar el descriptor siguiente como guía de mejora.", "Habilitar la revisión: Dar tiempo y una fecha para entregar una nueva versión."]}, {"title": "En el aula", "text": "El profesor devuelve los informes de un problema con un solo criterio marcado: «justifica el procedimiento». Escribe: «Estás en proceso; para llegar a logrado, explicá por qué elegiste ese cálculo». En la clase siguiente, cada estudiante reescribe su justificación y vuelve a entregar."}, {"title": "Paso a paso", "items": ["Elegí el criterio más importante para mejorar.", "Usá el descriptor del nivel siguiente para orientar.", "Escribí una acción concreta.", "Dá tiempo y fecha para una nueva versión."]}, {"title": "Cuidado con…", "items": ["Marcar todos los criterios sin priorizar.", "Devolver solo cruces y una nota.", "No permitir revisiones después de la devolución."]}], "practice": "Segunda versión: Que los estudiantes usen la devolución con rúbrica para mejorar su trabajo. La consigna completa está en la guía de la lección."} },
  'ei-1-1': { video: { src: m55, poster: m56, title: "Una mirada inclusiva", duration: "1 min 41 s", objective: "Comprender la diversidad como condición de todo grupo y la inclusión como tarea de la enseñanza.", reflection: "¿Quién podría quedar afuera de tu próxima actividad, y qué podrías anticipar?" }, guide: { label: "Guía: Una mirada inclusiva de la diversidad.pdf", href: m57 }, reading: {"type": "guide", "keyIdea": "Todos los grupos son diversos: en ritmos, intereses, lenguas, historias y formas de aprender. Una enseñanza inclusiva anticipa esas diferencias para que no se conviertan en desigualdades.", "objectives": ["Reconocer la diversidad como rasgo de todo grupo.", "Distinguir diferencia de desigualdad.", "Identificar decisiones de enseñanza que incluyen o excluyen."], "sections": [{"title": "La idea central", "text": "La diversidad es una condición de todo grupo; la inclusión es una decisión de enseñanza. Incluir no es dar lo mismo a todos, sino que todos puedan aprender lo valioso."}, {"title": "Tres ideas para empezar", "items": ["Todos son diversos: No es una característica de algunos estudiantes, sino de cualquier grupo.", "Diferencia y desigualdad: Las diferencias se vuelven desigualdades cuando la propuesta deja a algunos afuera.", "Anticipar: Pensar desde el inicio en quiénes podrían quedar afuera y cómo evitarlo."]}, {"title": "En el aula", "text": "En un grupo de cuarto grado hay chicos que leen con fluidez y otros que recién empiezan. La docente no separa al grupo: propone el mismo cuento con audio, imágenes y una versión con letra más grande. Todos trabajan el mismo contenido y comparten sus ideas en la puesta en común."}, {"title": "Paso a paso", "items": ["Pensá en tu grupo real, no en un alumno promedio.", "Identificá quiénes podrían quedar afuera de tu próxima actividad.", "Ofrecé más de una forma de acceder a la consigna.", "Mantené el mismo objetivo para todos."]}, {"title": "Cuidado con…", "items": ["Pensar la inclusión solo para estudiantes con diagnóstico.", "Bajar el objetivo en lugar de ofrecer apoyos.", "Separar al grupo de forma permanente por niveles."]}], "practice": "Mapa del grupo: Mirar la diversidad del grupo para anticipar decisiones de enseñanza. La consigna completa está en la guía de la lección."} },
  'ei-1-2': { video: { src: m58, poster: m59, title: "Identificar barreras", duration: "1 min 38 s", objective: "Analizar barreras físicas, comunicacionales, didácticas y actitudinales para intervenir sobre el contexto.", reflection: "¿Qué barrera comunicacional podría tener la consigna de tu próxima actividad?" }, guide: { label: "Guía: Identificación de barreras.pdf", href: m60 }, reading: {"type": "guide", "keyIdea": "Las dificultades no están solo en las personas: muchas veces están en el contexto. Identificar las barreras permite cambiar la propuesta en lugar de esperar que el estudiante se adapte.", "objectives": ["Reconocer distintos tipos de barreras.", "Ubicar las barreras en el contexto, no en la persona.", "Proponer cambios concretos para reducirlas."], "sections": [{"title": "La idea central", "text": "Una barrera es algo del contexto que limita el aprendizaje o la participación. Si la barrera está en el contexto, también está a nuestro alcance cambiarla."}, {"title": "Tipos de barreras", "items": ["Físicas: Espacios, mobiliario o materiales que no todos pueden usar.", "Comunicacionales: Consignas largas, solo orales o solo escritas, vocabulario no explicado.", "Actitudinales: Expectativas bajas o etiquetas que limitan lo que se cree que alguien puede lograr."]}, {"title": "En el aula", "text": "Un estudiante no responde las preguntas sobre un texto largo. El profesor descubre que la barrera es la extensión del texto y el vocabulario, no el tema. Ofrece el texto dividido en partes, con un glosario y preguntas intermedias, y el estudiante participa."}, {"title": "Paso a paso", "items": ["Observá en qué momento alguien deja de participar.", "Preguntate qué del contexto puede estar influyendo.", "Clasificá la barrera: física, comunicacional, didáctica o actitudinal.", "Probá un cambio en la propuesta y observá el efecto."]}, {"title": "Cuidado con…", "items": ["Atribuir toda dificultad a la persona.", "Esperar un diagnóstico para hacer cambios.", "Ver la barrera y no cambiar nada de la propuesta."]}], "practice": "Cazadores de barreras: Revisar una actividad propia para identificar y reducir barreras. La consigna completa está en la guía de la lección."} },
  'ei-2-1': { video: { src: m61, poster: m62, title: "Diseño universal para el aprendizaje", duration: "1 min 41 s", objective: "Conocer el diseño universal para el aprendizaje y aplicarlo al planificar.", reflection: "¿Qué segunda forma de presentar la información podrías sumar a tu próxima clase?" }, guide: { label: "Guía: Diseño universal para el aprendizaje.pdf", href: m63 }, reading: {"type": "guide", "keyIdea": "El diseño universal para el aprendizaje (DUA) propone planificar desde el inicio con varias formas de presentar la información, de participar y de mostrar lo aprendido. Lo que es imprescindible para algunos suele ser útil para todos.", "objectives": ["Conocer los tres principios del DUA.", "Aplicarlos al planificar una clase.", "Distinguir el DUA de las adaptaciones posteriores."], "sections": [{"title": "La idea central", "text": "El DUA propone planificar con varias formas de acceder, participar y expresar lo aprendido. Lo que es imprescindible para algunos suele ser útil para todos."}, {"title": "Los tres principios", "items": ["Representación: Presentar la información de varias formas: texto, imagen, audio, objetos.", "Acción y expresión: Permitir mostrar lo aprendido de distintas maneras: oral, escrito, dibujo, maqueta.", "Implicación: Despertar interés y sostener el esfuerzo con opciones y propósitos claros."]}, {"title": "En el aula", "text": "Para enseñar las partes de la planta, la docente lleva plantas reales, un video corto y un esquema. Cada chico elige cómo mostrar lo que aprendió: un dibujo con rótulos, una explicación grabada o una maqueta. Todos responden a los mismos criterios: nombrar las partes y explicar su función."}, {"title": "Paso a paso", "items": ["Definí el objetivo y los criterios comunes.", "Pensá al menos dos formas de presentar la información.", "Ofrecé opciones para mostrar lo aprendido.", "Conectá la tarea con algo que le importe al grupo."]}, {"title": "Cuidado con…", "items": ["Pensar el DUA como una adaptación para algunos.", "Ofrecer tantas opciones que el grupo se pierde.", "Cambiar el objetivo según la opción elegida."]}], "practice": "Una clase, tres caminos: Rediseñar una clase aplicando los tres principios del DUA. La consigna completa está en la guía de la lección."} },
  'ei-2-2': { video: { src: m64, poster: m65, title: "Convivencia y pertenencia", duration: "1 min 33 s", objective: "Construir vínculos y participación que sostengan el sentido de pertenencia.", reflection: "¿Qué estudiante de tu grupo necesita sentirse más parte, y qué podrías hacer esta semana?" }, guide: { label: "Guía: Convivencia y sentido de pertenencia.pdf", href: m66 }, reading: {"type": "guide", "keyIdea": "La inclusión no es solo una cuestión didáctica: también se construye en los vínculos. Sentirse parte del grupo, ser escuchado y tener un lugar real en las decisiones hace posible aprender.", "objectives": ["Reconocer la importancia del sentido de pertenencia.", "Diseñar momentos de escucha y participación real.", "Intervenir ante situaciones de exclusión."], "sections": [{"title": "La idea central", "text": "Sentirse parte del grupo es una condición para aprender. La pertenencia se construye todos los días, con gestos pequeños y sostenidos."}, {"title": "Cómo construir pertenencia", "items": ["Escuchar: Dar lugar a lo que cada uno trae: su historia, su lengua, sus intereses.", "Roles para todos: Que cada estudiante tenga una tarea valiosa en los trabajos en grupo.", "Intervenir: No dejar pasar burlas ni exclusiones: nombrarlas y trabajarlas con el grupo."]}, {"title": "En el aula", "text": "Una estudiante que llegó de otra provincia casi no habla en clase. La tutora propone una ronda en la que cada uno cuenta una comida típica de su familia. Ella comparte una receta de su lugar, el grupo pregunta, y desde ese día empieza a participar más."}, {"title": "Paso a paso", "items": ["Conocé algo de cada estudiante más allá de lo escolar.", "Rotá roles en los trabajos grupales.", "Intervení ante burlas o exclusiones en el momento.", "Generá espacios donde lo de cada uno tenga valor."]}, {"title": "Cuidado con…", "items": ["Pensar que la convivencia es tarea solo de preceptores o directivos.", "Armar siempre los mismos grupos.", "Dejar pasar «chistes» que excluyen."]}], "practice": "Ronda de lo que traemos: Reconocer y valorar lo que cada estudiante trae al grupo. La consigna completa está en la guía de la lección."} },
  'ei-3-1': { video: { src: m67, poster: m68, title: "Varias formas de representar", duration: "1 min 37 s", objective: "Presentar los contenidos de varias maneras para reducir barreras de acceso.", reflection: "¿Qué concepto de tu área podrías presentar con un objeto, un esquema y un texto breve?" }, guide: { label: "Guía: Múltiples formas de representación.pdf", href: m69 }, reading: {"type": "guide", "keyIdea": "Cuando un concepto se presenta solo de una forma, quien no accede a esa forma queda afuera. Combinar texto claro, ejemplos, esquemas, imágenes y audio abre más puertas al mismo contenido.", "objectives": ["Combinar distintos formatos para presentar un concepto.", "Hacer explícito el vocabulario clave.", "Usar ejemplos y esquemas para apoyar la comprensión."], "sections": [{"title": "La idea central", "text": "Presentar el mismo contenido de varias formas abre más puertas para comprenderlo. No se trata de hacer más, sino de elegir bien qué formato suma."}, {"title": "Formas de representar", "items": ["Texto claro: Oraciones cortas, palabras conocidas y títulos que orientan.", "Esquemas e imágenes: Un mapa conceptual o una imagen rotulada muestran relaciones.", "Audio y objetos: Una explicación grabada o un objeto real que se pueda tocar."]}, {"title": "En el aula", "text": "Para enseñar fracciones, la docente usa una pizza de cartón, un dibujo en el pizarrón y la escritura numérica. Además deja un audio corto con la explicación, para escuchar en casa. Los chicos pasan de un formato a otro: cortan, dibujan y escriben la misma fracción."}, {"title": "Paso a paso", "items": ["Identificá el concepto más difícil de tu próxima clase.", "Elegí al menos dos formatos para presentarlo.", "Explicá el vocabulario clave con ejemplos.", "Proponé pasar de un formato a otro."]}, {"title": "Cuidado con…", "items": ["Presentar todo en un solo formato.", "Sumar imágenes decorativas que no explican nada.", "Dar por sabido el vocabulario técnico."]}], "practice": "El mismo concepto, tres formatos: Que el grupo comprenda un concepto pasando por distintas representaciones. La consigna completa está en la guía de la lección."} },
  'ei-3-2': { video: { src: m70, poster: m71, title: "Varias formas de participar", duration: "1 min 36 s", objective: "Ofrecer opciones para responder y participar sosteniendo objetivos comunes.", reflection: "¿Qué evaluación tuya podría ofrecer una segunda forma de respuesta?" }, guide: { label: "Guía: Múltiples formas de acción y participación.pdf", href: m72 }, reading: {"type": "guide", "keyIdea": "Mostrar lo aprendido no tiene por qué ser siempre de la misma forma. Ofrecer opciones de respuesta permite que más estudiantes demuestren lo que saben, con los mismos criterios para todos.", "objectives": ["Ofrecer distintas formas de mostrar lo aprendido.", "Mantener criterios comunes entre opciones.", "Acompañar la elección de cada estudiante."], "sections": [{"title": "La idea central", "text": "Opciones distintas para mostrar lo aprendido, con criterios comunes para todos. Flexibilizar el camino no significa bajar la exigencia."}, {"title": "Cómo ofrecer opciones", "items": ["Un menú acotado: Dos o tres opciones: un texto, una exposición oral, un esquema explicado.", "Los mismos criterios: Todas las opciones se evalúan con los mismos criterios de aprendizaje.", "Ayuda para elegir: Acompañar la elección para que sea un desafío posible, no una vía de escape."]}, {"title": "En el aula", "text": "Para mostrar lo que aprendieron sobre el sistema digestivo, los estudiantes eligen entre tres opciones. Pueden escribir un informe, grabar un audio explicando un esquema o armar una maqueta rotulada. Todas se evalúan con los mismos criterios: nombrar los órganos, explicar su función y relacionarlos."}, {"title": "Paso a paso", "items": ["Definí los criterios de aprendizaje primero.", "Ofrecé dos o tres opciones que permitan cumplirlos.", "Mostrá un ejemplo de cada opción.", "Acompañá la elección según las fortalezas y desafíos de cada uno."]}, {"title": "Cuidado con…", "items": ["Ofrecer opciones con distinta exigencia.", "Dar opciones sin criterios claros.", "Permitir siempre la opción más cómoda sin desafío."]}], "practice": "Menú de evidencias: Ofrecer opciones para mostrar un mismo aprendizaje con criterios comunes. La consigna completa está en la guía de la lección."} },
  'ef-1-1': { video: { src: m73, poster: m74, title: "Evaluar para acompañar", duration: "1 min 42 s", objective: "Comprender la evaluación formativa como información para decidir durante la enseñanza.", reflection: "¿Qué evidencia breve podrías recoger mañana para saber cómo va tu grupo?" }, guide: { label: "Guía: Evaluar para acompañar el aprendizaje.pdf", href: m75 }, reading: {"type": "guide", "keyIdea": "La evaluación formativa no es una nota: es información que se recoge mientras se aprende para decidir qué hacer después, tanto el docente como el estudiante.", "objectives": ["Distinguir evaluación formativa y sumativa.", "Reconocer evidencias que se recogen durante la clase.", "Usar la información para decidir el próximo paso."], "sections": [{"title": "La idea central", "text": "Evaluar para acompañar es recoger información durante el proceso para decidir qué enseñar después. Lo formativo no depende del instrumento, sino de lo que hacemos con la información."}, {"title": "Tres preguntas que guían", "items": ["¿Hacia dónde vamos?: Compartir con el grupo qué se espera aprender y cómo se va a reconocer.", "¿Dónde estamos?: Recoger evidencias breves: una pregunta, un ejercicio, una explicación oral.", "¿Cómo seguimos?: Decidir el próximo paso: repasar, profundizar o cambiar la estrategia."]}, {"title": "En el aula", "text": "Antes de terminar la clase de fracciones, la docente pide que cada uno resuelva un problema en un papelito. Al leerlos, ve que la mitad suma numeradores y denominadores por separado. Al día siguiente empieza con ese error, usando material concreto, en lugar de avanzar con el tema nuevo."}, {"title": "Paso a paso", "items": ["Compartí el objetivo de la clase en palabras simples.", "Planificá una pregunta breve para la mitad o el final.", "Mirá las respuestas buscando patrones, no solo aciertos.", "Decidí qué cambiar en la próxima clase y contáselo al grupo."]}, {"title": "Cuidado con…", "items": ["Recoger evidencias y no usarlas para decidir nada.", "Confundir evaluación formativa con poner más notas.", "Mirar solo quién acertó, sin analizar por qué se equivocaron."]}], "practice": "Boleto de salida: Recoger en pocos minutos información sobre lo que el grupo comprendió en la clase. La consigna completa está en la guía de la lección."} },
  'ef-1-2': { video: { src: m76, poster: m77, title: "Criterios e instrumentos", duration: "1 min 41 s", objective: "Alinear objetivos, criterios e instrumentos para observar aprendizajes relevantes.", reflection: "¿Qué objetivo de tu próxima clase podrías traducir en dos criterios observables?" }, guide: { label: "Guía: Criterios e instrumentos.pdf", href: m78 }, reading: {"type": "guide", "keyIdea": "Un buen criterio describe qué vamos a mirar en el desempeño, y el instrumento tiene que permitir verlo. Si el objetivo, el criterio y la evidencia no están alineados, la evaluación mide otra cosa.", "objectives": ["Formular criterios a partir de objetivos.", "Elegir instrumentos que permitan observar esos criterios.", "Compartir los criterios con los estudiantes."], "sections": [{"title": "La idea central", "text": "Objetivo, criterio y evidencia tienen que apuntar al mismo aprendizaje. Cuando están alineados, la evaluación mide lo que realmente enseñamos."}, {"title": "Del objetivo al instrumento", "items": ["Objetivo: Qué se espera que el estudiante logre, por ejemplo, explicar el ciclo del agua.", "Criterio: Qué rasgo del desempeño vamos a mirar: nombra las etapas y las relaciona.", "Instrumento: Cómo lo vamos a observar: un esquema explicado, una lista de cotejo o una rúbrica."]}, {"title": "En el aula", "text": "El profesor quiere evaluar si sus estudiantes explican el ciclo del agua. En lugar de una prueba con opciones, les pide un esquema con flechas y una explicación oral de dos minutos. Antes de empezar, muestra los criterios: etapas correctas, relaciones entre etapas y uso del vocabulario."}, {"title": "Paso a paso", "items": ["Escribí el objetivo con un verbo que se pueda observar.", "Definí dos o tres criterios que describan un buen desempeño.", "Elegí un instrumento que permita ver esos criterios.", "Compartí los criterios antes de la tarea, con un ejemplo."]}, {"title": "Cuidado con…", "items": ["Usar criterios vagos como «buena presentación» o «interés».", "Elegir el instrumento antes de definir qué se quiere observar.", "Dar a conocer los criterios recién al devolver la nota."]}], "practice": "Criterios con ejemplos: Que el grupo comprenda los criterios antes de hacer la tarea, a partir de ejemplos concretos. La consigna completa está en la guía de la lección."} },
  'ef-2-1': { video: { src: m79, poster: m80, title: "Retroalimentación que ayuda", duration: "1 min 37 s", objective: "Dar devoluciones específicas que reconozcan avances y propongan un próximo paso.", reflection: "¿Qué cambiarías en la próxima devolución que escribas?" }, guide: { label: "Guía: Retroalimentación efectiva.pdf", href: m81 }, reading: {"type": "guide", "keyIdea": "Una buena devolución dice qué se logró, qué mejorar y cómo hacerlo, en relación con los criterios. Y sirve solo si el estudiante tiene la oportunidad de usarla.", "objectives": ["Reconocer las partes de una devolución útil.", "Formular comentarios específicos y accionables.", "Generar momentos para usar la devolución."], "sections": [{"title": "La idea central", "text": "Una devolución útil reconoce un logro, señala una mejora concreta y propone un próximo paso. Si llega tarde o es muy general, el estudiante no sabe qué hacer con ella."}, {"title": "Tres partes de una devolución", "items": ["Lo logrado: Nombrar algo concreto que está bien, para que el estudiante sepa qué sostener.", "Lo que falta: Señalar una sola mejora importante, ligada a un criterio.", "El próximo paso: Proponer una acción posible: revisar, agregar un ejemplo, reescribir un párrafo."]}, {"title": "En el aula", "text": "En lugar de «Falta desarrollo», la profesora escribe: «Tu opinión es clara. Para convencer, sumá un argumento con un ejemplo de tu barrio». En la clase siguiente, dedica quince minutos a que cada estudiante reescriba ese párrafo."}, {"title": "Paso a paso", "items": ["Elegí un criterio en el que te vas a enfocar.", "Escribí un logro concreto antes de señalar la mejora.", "Proponé una acción que el estudiante pueda hacer solo.", "Reservá tiempo en clase para usar la devolución."]}, {"title": "Cuidado con…", "items": ["Corregir todo a la vez: el estudiante no sabe por dónde empezar.", "Devolver con nota y comentario juntos: suele leerse solo la nota.", "Dar la devolución cuando ya no hay oportunidad de mejorar."]}], "practice": "Dos estrellas y un deseo: Practicar devoluciones que combinan logros y una mejora concreta. La consigna completa está en la guía de la lección."} },
  'ef-2-2': { video: { src: m82, poster: m83, title: "Autoevaluación y pares", duration: "1 min 38 s", objective: "Usar la autoevaluación y la revisión entre pares para que los estudiantes se apropien de los criterios.", reflection: "¿En qué tarea podrías sumar una revisión entre compañeros antes de la entrega?" }, guide: { label: "Guía: Autoevaluación y evaluación entre pares.pdf", href: m84 }, reading: {"type": "guide", "keyIdea": "Cuando los estudiantes usan los criterios para mirar su trabajo y el de otros, aprenden a reconocer la calidad y a mejorar por sí mismos. Necesita criterios claros, práctica y un clima de respeto.", "objectives": ["Diseñar momentos de autoevaluación con criterios.", "Organizar revisiones entre pares respetuosas.", "Usar lo que surge para mejorar las producciones."], "sections": [{"title": "La idea central", "text": "Evaluarse y evaluar a otros ayuda a entender qué es un buen trabajo y cómo mejorarlo. No se trata de poner notas entre compañeros, sino de aprender a mirar con criterios."}, {"title": "Cómo hacer que funcione", "items": ["Criterios a la vista: Una lista breve y clara, con ejemplos de cómo se ve cada criterio.", "Frases para comentar: «Me gustó…», «Me pregunto…», «Podrías…» ayudan a que la devolución sea respetuosa.", "Una nueva versión: Después de revisar, el estudiante decide qué cambiar y mejora su trabajo."]}, {"title": "En el aula", "text": "Antes de entregar un cuento, cada chico lo revisa con una lista de tres preguntas. ¿Tiene un problema? ¿Se resuelve? ¿Se entiende quién habla? Después lo intercambian con un compañero, que marca una cosa que le gustó y hace una pregunta."}, {"title": "Paso a paso", "items": ["Elegí dos o tres criterios y escribilos como preguntas.", "Mostrá cómo se usan revisando un trabajo anónimo en voz alta.", "Acordá frases para comentar y un tono respetuoso.", "Dejá tiempo para que cada uno mejore su producción."]}, {"title": "Cuidado con…", "items": ["Pedir que se pongan notas entre compañeros.", "Dar una lista de criterios demasiado larga.", "Hacer la revisión sin tiempo para corregir después."]}], "practice": "Revisión con tres preguntas: Que los estudiantes usen criterios para revisar y mejorar una producción propia y una ajena. La consigna completa está en la guía de la lección."} },
  'ef-3-1': { video: { src: m85, poster: m86, title: "Formularios para diagnosticar", duration: "1 min 40 s", objective: "Diseñar formularios breves para conocer ideas previas y errores frecuentes antes de enseñar.", reflection: "¿Qué pregunta diagnóstica podrías hacer antes de tu próximo tema?" }, guide: { label: "Guía: Formularios para diagnosticar.pdf", href: m87 }, reading: {"type": "guide", "keyIdea": "Un formulario corto, con preguntas bien pensadas, muestra en minutos qué sabe el grupo y qué errores trae. Lo importante no es el puntaje: es qué decidís hacer con esas respuestas.", "objectives": ["Formular preguntas diagnósticas que revelen ideas previas.", "Usar opciones que representen errores frecuentes.", "Planificar la clase a partir de los resultados."], "sections": [{"title": "La idea central", "text": "Un buen diagnóstico es breve, apunta a lo esencial y se usa para planificar. Puede ser digital o en papel: lo que importa es la calidad de las preguntas."}, {"title": "Cómo armar un buen diagnóstico", "items": ["Una idea clave por pregunta: Cada pregunta apunta a un saber necesario para el tema que viene.", "Opciones con errores reales: Las opciones incorrectas reflejan confusiones típicas, así sabés qué piensa el grupo.", "Una pregunta abierta: «Explicá cómo lo pensaste» muestra el razonamiento detrás de la respuesta."]}, {"title": "En el aula", "text": "Antes de enseñar fuerzas, el profesor arma un formulario de cuatro preguntas. Una opción dice que un objeto se detiene porque «se le acaba la fuerza», una idea muy común. Como la mitad del curso la elige, decide empezar con un experimento que discuta esa idea."}, {"title": "Paso a paso", "items": ["Definí qué saberes necesita el grupo para el tema nuevo.", "Escribí entre tres y cinco preguntas, una por saber.", "Incluí opciones que representen errores frecuentes.", "Revisá los resultados y ajustá el inicio de la secuencia."]}, {"title": "Cuidado con…", "items": ["Hacer formularios largos que cansan y no se analizan.", "Calificar el diagnóstico: el objetivo es conocer, no aprobar.", "Usar solo la versión digital si no todos tienen conexión."]}], "practice": "Diagnóstico en cuatro preguntas: Conocer ideas previas y errores frecuentes antes de empezar un tema nuevo. La consigna completa está en la guía de la lección."} },
  'ef-3-2': { video: { src: m88, poster: m89, title: "Portafolios para ver procesos", duration: "1 min 35 s", objective: "Usar portafolios para observar cambios a lo largo del tiempo a partir de versiones y reflexiones.", reflection: "¿Qué producción de tus estudiantes valdría la pena ver en dos versiones?" }, guide: { label: "Guía: Portafolios para ver procesos.pdf", href: m90 }, reading: {"type": "guide", "keyIdea": "Un portafolio no es una carpeta de trabajos terminados: reúne versiones, devoluciones y reflexiones que muestran cómo cambió el aprendizaje. Puede ser en papel o digital.", "objectives": ["Definir qué producciones incluir en un portafolio.", "Promover reflexiones breves sobre el propio proceso.", "Usar el portafolio para dialogar sobre el progreso."], "sections": [{"title": "La idea central", "text": "Un portafolio muestra el camino del aprendizaje, no solo el resultado. Comparar un primer borrador con la versión final ayuda a ver y valorar el progreso."}, {"title": "Qué incluir", "items": ["Versiones: Un primer borrador y una versión mejorada del mismo trabajo.", "Devoluciones: Los comentarios recibidos y qué se hizo con ellos.", "Reflexión: Unas líneas del estudiante: qué aprendí, qué me costó y qué haría distinto."]}, {"title": "En el aula", "text": "A lo largo del trimestre, cada estudiante guarda tres producciones en una carpeta compartida. Al final elige la que muestra más avance y escribe por qué, comparando la primera y la última versión. La profesora usa esa reflexión en una charla breve con cada uno para acordar metas."}, {"title": "Paso a paso", "items": ["Definí qué tipo de producciones va a reunir el portafolio.", "Pedí que guarden borradores, no solo versiones finales.", "Proponé reflexiones breves con preguntas guía.", "Usá el portafolio en una charla sobre progreso y metas."]}, {"title": "Cuidado con…", "items": ["Convertir el portafolio en un archivo de todo lo que se hizo.", "Pedir reflexiones largas que se vuelven una tarea más.", "Revisarlo solo al final, cuando ya no hay tiempo de mejorar."]}], "practice": "Antes y después: Que los estudiantes reconozcan su propio progreso comparando dos versiones de un trabajo. La consigna completa está en la guía de la lección."} },
  'da-1-1': { video: { src: m91, poster: m92, title: "Objetivos que orientan", duration: "1 min 38 s", objective: "Formular objetivos claros que orienten actividades y evidencias.", reflection: "¿Qué evidencia mostraría que tu grupo logró el objetivo de tu próxima secuencia?" }, guide: { label: "Guía: Objetivos y resultados esperados.pdf", href: m93 }, reading: {"type": "guide", "keyIdea": "Diseñar empieza por el final: qué queremos que los estudiantes aprendan y cómo nos vamos a dar cuenta. Con eso claro, las actividades dejan de ser una suma de tareas.", "objectives": ["Formular objetivos centrados en el aprendizaje.", "Definir qué evidencia mostraría que se logró.", "Elegir actividades a partir del objetivo."], "sections": [{"title": "La idea central", "text": "Un buen diseño parte de lo que se quiere aprender y de cómo se va a reconocer. Las actividades son el camino, no el destino."}, {"title": "Diseñar empezando por el final", "items": ["Qué aprender: Un objetivo con un verbo observable: explicar, comparar, resolver, producir.", "Cómo reconocerlo: La evidencia que mostraría el logro: una explicación, un problema resuelto, un texto.", "Qué hacer: Recién entonces, las actividades que llevan a esa evidencia."]}, {"title": "En el aula", "text": "La docente quiere que su grupo compare la vida en el campo y en la ciudad. Primero define la evidencia: un cuadro comparativo con tres criterios y una conclusión. Después elige las actividades: entrevistas a familiares, fotos del barrio y lectura de testimonios."}, {"title": "Paso a paso", "items": ["Escribí qué tienen que aprender, con un verbo observable.", "Definí qué producción mostraría ese aprendizaje.", "Elegí actividades que preparen para esa producción.", "Revisá que cada actividad aporte al objetivo."]}, {"title": "Cuidado con…", "items": ["Empezar por la actividad y buscarle un objetivo después.", "Usar verbos vagos como «conocer» o «comprender» sin precisar.", "Planificar más actividades de las que el tiempo permite."]}], "practice": "Del objetivo a la evidencia: Revisar una planificación propia empezando por el final. La consigna completa está en la guía de la lección."} },
  'da-1-2': { video: { src: m94, poster: m95, title: "Secuencias con sentido", duration: "1 min 31 s", objective: "Organizar inicio, desarrollo y cierre como momentos articulados.", reflection: "¿Cómo podrías cerrar tu próxima clase para que el grupo sintetice lo aprendido?" }, guide: { label: "Guía: Secuencias con sentido.pdf", href: m96 }, reading: {"type": "guide", "keyIdea": "Una secuencia tiene sentido cuando cada momento cumple una función: el inicio despierta y recupera saberes, el desarrollo permite practicar con apoyo y el cierre ayuda a sintetizar.", "objectives": ["Reconocer la función de cada momento de una secuencia.", "Articular actividades para que una prepare la siguiente.", "Diseñar cierres que sinteticen lo aprendido."], "sections": [{"title": "La idea central", "text": "Inicio, desarrollo y cierre no son partes del horario: son momentos con funciones distintas. Cuando cada momento cumple su función, la secuencia avanza con sentido."}, {"title": "Tres momentos, tres funciones", "items": ["Inicio: Presentar el desafío y recuperar lo que el grupo ya sabe.", "Desarrollo: Practicar con apoyo, primero acompañados y después con más autonomía.", "Cierre: Sintetizar qué se aprendió, cómo y qué falta."]}, {"title": "En el aula", "text": "El profesor empieza con una pregunta: ¿cuánto pagamos de más si compramos en cuotas? En el desarrollo, los grupos calculan porcentajes con folletos reales, primero con ayuda y después solos. Para cerrar, cada grupo escribe una regla con sus palabras y la comparan."}, {"title": "Paso a paso", "items": ["Planificá el cierre antes que el resto.", "Diseñá un inicio que plantee una pregunta o un problema.", "Ordená el desarrollo de lo más guiado a lo más autónomo.", "Reservá al menos diez minutos para cerrar."]}, {"title": "Cuidado con…", "items": ["Usar el inicio solo para dar instrucciones.", "Dejar el cierre para «si sobra tiempo».", "Encadenar actividades que no se relacionan entre sí."]}], "practice": "Mapa de la secuencia: Visualizar una secuencia y revisar la función de cada momento. La consigna completa está en la guía de la lección."} },
  'da-2-1': { video: { src: m97, poster: m98, title: "Aprender con desafíos", duration: "1 min 35 s", objective: "Diseñar desafíos auténticos que inviten a investigar, decidir y producir.", reflection: "¿Qué contenido de tu planificación podría convertirse en un desafío del barrio o la escuela?" }, guide: { label: "Guía: Aprendizaje basado en desafíos.pdf", href: m99 }, reading: {"type": "guide", "keyIdea": "Un desafío auténtico parte de una situación real o verosímil, admite más de una solución y obliga a usar lo aprendido para decidir. Eso le da sentido al contenido.", "objectives": ["Reconocer las características de un desafío auténtico.", "Transformar un contenido en un desafío.", "Acompañar a los grupos durante la resolución."], "sections": [{"title": "La idea central", "text": "Un desafío auténtico plantea un problema real que solo se resuelve usando lo que se está aprendiendo. El contenido deja de ser un fin y se vuelve una herramienta."}, {"title": "Qué tiene un buen desafío", "items": ["Contexto cercano: Una situación de la escuela, el barrio o la comunidad.", "Más de una respuesta: Hay varias soluciones posibles y hay que justificar la elegida.", "Un producto: Algo concreto para mostrar: una propuesta, un plano, una campaña."]}, {"title": "En el aula", "text": "El desafío: el patio se inunda cada vez que llueve, ¿qué podemos proponer? Los grupos observan el patio, miden, investigan cómo se mueve el agua y dibujan propuestas. Al final presentan sus ideas a la directora, explicando por qué funcionarían."}, {"title": "Paso a paso", "items": ["Elegí un contenido que quieras enseñar.", "Buscá una situación real en la que ese contenido sea útil.", "Formulá el desafío como una pregunta abierta.", "Definí qué producto van a presentar y a quién."]}, {"title": "Cuidado con…", "items": ["Plantear un desafío que se resuelve sin usar el contenido.", "Dar tan pocas pistas que el grupo se frustra.", "Elegir un producto final que lleva más tiempo que aprender."]}], "practice": "Convertir un tema en desafío: Practicar la transformación de un contenido curricular en un desafío auténtico. La consigna completa está en la guía de la lección."} },
  'da-2-2': { video: { src: m100, poster: m101, title: "Participación y reflexión", duration: "1 min 39 s", objective: "Diseñar oportunidades para que todos participen y reflexionen sobre cómo aprendieron.", reflection: "¿Quiénes participan menos en tu grupo y qué forma de aportar podrías ofrecerles?" }, guide: { label: "Guía: Participación y reflexión.pdf", href: m102 }, reading: {"type": "guide", "keyIdea": "Que todos participen no ocurre solo: hay que diseñarlo con distintas formas de aportar. Y reflexionar sobre cómo se aprendió ayuda a que cada estudiante gane autonomía.", "objectives": ["Diseñar estrategias para ampliar la participación.", "Ofrecer distintas formas de aportar.", "Incluir momentos breves de reflexión sobre el aprendizaje."], "sections": [{"title": "La idea central", "text": "La participación se diseña: distintas formas de aportar y momentos para pensar sobre lo aprendido. Pensar sobre cómo se aprendió es tan importante como lo que se aprendió."}, {"title": "Estrategias que suman voces", "items": ["Pensar, compartir: Un minuto para pensar solo, después en parejas y recién después en el grupo.", "Varias formas: Aportar hablando, escribiendo, dibujando o con una votación anónima.", "Mirar el proceso: ¿Qué me ayudó? ¿Dónde me trabé? ¿Qué haría distinto?"]}, {"title": "En el aula", "text": "Antes de debatir sobre un texto, la profesora da dos minutos para escribir una idea. Después la comparten en parejas y cada pareja elige una para decir en voz alta. Al final, cada estudiante completa: «Hoy entendí mejor cuando…»."}, {"title": "Paso a paso", "items": ["Antes de preguntar al grupo, dá un tiempo para pensar.", "Ofrecé al menos dos formas de participar.", "Usá las parejas como paso previo a hablar en el grupo.", "Cerrá con una pregunta sobre cómo aprendieron."]}, {"title": "Cuidado con…", "items": ["Preguntar y aceptar la primera mano levantada.", "Pedir siempre la misma forma de participar.", "Hacer la reflexión tan larga que se vuelve una tarea más."]}], "practice": "Pensar, compartir en parejas, compartir con todos: Ampliar la participación dando tiempo para pensar y un espacio seguro antes de hablar en grupo. La consigna completa está en la guía de la lección."} },
  'da-3-1': { video: { src: m103, poster: m104, title: "Tiempos y apoyos", duration: "1 min 32 s", objective: "Planificar una secuencia viable que anticipe tiempos, agrupamientos, recursos y apoyos.", reflection: "¿Qué apoyo podrías dejar preparado para tu próxima clase?" }, guide: { label: "Guía: Planificar tiempos y apoyos.pdf", href: m105 }, reading: {"type": "guide", "keyIdea": "Una buena idea puede fracasar por falta de tiempo o de apoyos. Planificar es anticipar cuánto lleva cada momento, cómo se agrupan, qué recursos hacen falta y qué ayudas ofrecer.", "objectives": ["Estimar tiempos de forma realista.", "Elegir agrupamientos según la tarea.", "Anticipar apoyos para distintos ritmos."], "sections": [{"title": "La idea central", "text": "Una planificación viable anticipa tiempos, agrupamientos, recursos y apoyos. Anticipar no quita flexibilidad: da margen para ajustar."}, {"title": "Qué anticipar", "items": ["Tiempos: Cuánto lleva cada momento, con un margen para imprevistos.", "Agrupamientos: Individual, parejas o grupos, según lo que pide la tarea.", "Apoyos: Ayudas preparadas: un ejemplo resuelto, un glosario, una versión más guiada."]}, {"title": "En el aula", "text": "La docente planifica una clase de problemas con tres niveles de ayuda. Quien se traba puede pedir una tarjeta con una pista; quien termina, una con un desafío extra. Así todos trabajan el mismo problema, con distintos apoyos."}, {"title": "Paso a paso", "items": ["Estimá el tiempo de cada momento y sumale un margen.", "Decidí el agrupamiento según la tarea, no por costumbre.", "Prepará al menos un apoyo para quien se traba.", "Prepará un desafío extra para quien termina antes."]}, {"title": "Cuidado con…", "items": ["Planificar como si todos trabajaran al mismo ritmo.", "Improvisar los apoyos en el momento.", "Cambiar de agrupamiento muchas veces en la misma clase."]}], "practice": "Tarjetas de ayuda: Ofrecer apoyos y desafíos graduados sin cambiar la actividad para todo el grupo. La consigna completa está en la guía de la lección."} },
  'da-3-2': { video: { src: m106, poster: m107, title: "Ajustar con evidencias", duration: "1 min 28 s", objective: "Usar producciones, preguntas y participación para ajustar la planificación.", reflection: "¿Qué evidencia de tu última clase te dice algo que deberías ajustar?" }, guide: { label: "Guía: Revisar la secuencia con evidencias.pdf", href: m108 }, reading: {"type": "guide", "keyIdea": "La planificación es una hipótesis: se pone a prueba en el aula. Mirar las producciones, las preguntas y la participación permite decidir qué mantener y qué cambiar.", "objectives": ["Registrar evidencias durante la secuencia.", "Analizarlas para decidir ajustes.", "Documentar los cambios para próximas veces."], "sections": [{"title": "La idea central", "text": "Planificar es formular una hipótesis; las evidencias del aula dicen cómo ajustarla. Ajustar no es fracasar: es enseñar mirando al grupo."}, {"title": "Qué mirar para ajustar", "items": ["Producciones: ¿Qué lograron y dónde se repiten los errores?", "Preguntas: ¿Qué preguntaron? Muestran qué no quedó claro.", "Participación: ¿Quiénes participaron y en qué momentos se desenganchó el grupo?"]}, {"title": "En el aula", "text": "Después de la primera clase, el profesor revisa los mapas del grupo. Ve que muchos confunden clima y tiempo, y que el trabajo en grupo se dispersó. Decide sumar un ejemplo con el pronóstico de la semana y asignar roles en los grupos."}, {"title": "Paso a paso", "items": ["Elegí qué evidencia vas a mirar en cada clase.", "Anotá en dos líneas qué pasó, al terminar.", "Buscá patrones: errores, preguntas o momentos repetidos.", "Decidí un ajuste concreto para la próxima clase."]}, {"title": "Cuidado con…", "items": ["Esperar al final de la secuencia para revisar.", "Cambiar todo por una mala clase.", "Ajustar sin registrar qué cambió y por qué."]}], "practice": "Bitácora de dos líneas: Registrar brevemente lo que pasa en cada clase para tomar decisiones con evidencias. La consigna completa está en la guía de la lección."} },
  'ga-1-1': { video: { src: m109, poster: m110, title: "Un clima para aprender", duration: "1 min 31 s", objective: "Reconocer qué condiciones del clima del aula favorecen la participación y el aprendizaje.", reflection: "¿Qué gesto cotidiano podrías sumar para que tu grupo se anime a preguntar más?" }, guide: { label: "Guía: Un clima que favorece el aprendizaje.pdf", href: m111 }, reading: {"type": "guide", "keyIdea": "Se aprende mejor cuando hay seguridad para preguntar y equivocarse, confianza en el vínculo y expectativas claras. El clima no aparece solo: se construye con decisiones cotidianas.", "objectives": ["Identificar rasgos de un clima favorable al aprendizaje.", "Reconocer el valor del error como parte de aprender.", "Comunicar expectativas claras y altas para todos."], "sections": [{"title": "La idea central", "text": "Un buen clima de aula da seguridad para participar, preguntar y equivocarse. El clima se construye con gestos pequeños que se repiten todos los días."}, {"title": "Qué construye un buen clima", "items": ["Seguridad: Equivocarse está permitido y nadie se burla de una pregunta.", "Confianza: Saludar por el nombre, interesarse, cumplir lo que se dice.", "Expectativas claras: Todos saben qué se espera y creen que pueden lograrlo."]}, {"title": "En el aula", "text": "Cuando un chico responde mal, la docente dice: «Buen error, nos ayuda a pensar. ¿Qué te llevó a esa respuesta?». El grupo analiza el razonamiento y encuentra juntos dónde estuvo la confusión. Con el tiempo, más chicos se animan a responder aunque no estén seguros."}, {"title": "Paso a paso", "items": ["Saludá a cada estudiante por su nombre.", "Tratá los errores como información para aprender.", "Explicá qué se espera en cada actividad.", "Intervení de inmediato ante burlas."]}, {"title": "Cuidado con…", "items": ["Corregir errores en público de forma que avergüence.", "Tener expectativas distintas según quién sea el estudiante.", "Pensar que el clima depende solo del grupo."]}], "practice": "El buen error de la semana: Valorar el error como parte de aprender y quitarle el miedo a equivocarse. La consigna completa está en la guía de la lección."} },
  'ga-1-2': { video: { src: m112, poster: m113, title: "Acuerdos y rutinas", duration: "1 min 33 s", objective: "Construir acuerdos con el grupo y rutinas que organicen tiempos, espacios y participación.", reflection: "¿Qué momento de tu clase necesita una rutina clara?" }, guide: { label: "Guía: Acuerdos y rutinas.pdf", href: m114 }, reading: {"type": "guide", "keyIdea": "Los acuerdos construidos con el grupo se respetan más que las reglas impuestas. Y las rutinas claras ahorran tiempo y dan tranquilidad: todos saben qué hacer en cada momento.", "objectives": ["Construir acuerdos de convivencia con el grupo.", "Diseñar rutinas para los momentos que se repiten.", "Enseñar y practicar acuerdos y rutinas."], "sections": [{"title": "La idea central", "text": "Los acuerdos dicen cómo queremos convivir; las rutinas, cómo hacemos lo que se repite. Un acuerdo que nadie recuerda no funciona: hay que enseñarlo y volver a él."}, {"title": "Acuerdos y rutinas que funcionan", "items": ["Acuerdos construidos: Surgen de conversar con el grupo sobre cómo queremos estar.", "Pocos y en positivo: Tres a cinco acuerdos, escritos como lo que sí hacemos.", "Rutinas para lo que se repite: Entrar, repartir materiales, trabajar en grupo, cerrar la clase."]}, {"title": "En el aula", "text": "El primer día, el tutor pregunta: ¿qué necesitamos para aprender bien juntos? Con las respuestas arman cuatro acuerdos en positivo y los pegan en el aula. Además definen una rutina de inicio: sentarse, sacar la carpeta y resolver una consigna breve del pizarrón."}, {"title": "Paso a paso", "items": ["Conversá con el grupo sobre qué necesitan para aprender.", "Escriban entre todos pocos acuerdos, en positivo.", "Elegí una rutina para un momento que se repite.", "Practicala varias veces al principio."]}, {"title": "Cuidado con…", "items": ["Imponer una lista larga de prohibiciones.", "Escribir los acuerdos y no volver a mencionarlos.", "Cambiar las rutinas todo el tiempo."]}], "practice": "Acuerdos en positivo: Construir con el grupo acuerdos de convivencia claros y compartidos. La consigna completa está en la guía de la lección."} },
  'ga-2-1': { video: { src: m115, poster: m116, title: "El conflicto como oportunidad", duration: "1 min 33 s", objective: "Abordar los conflictos escuchando perspectivas y construyendo reparaciones posibles.", reflection: "¿Cómo abordaste el último conflicto en tu grupo, y qué paso podrías sumar la próxima vez?" }, guide: { label: "Guía: El conflicto como oportunidad.pdf", href: m117 }, reading: {"type": "guide", "keyIdea": "Los conflictos son parte de la vida en grupo. No son lo mismo que la violencia: abordados a tiempo, con escucha y reglas claras, son una oportunidad para aprender a convivir.", "objectives": ["Distinguir conflicto y violencia.", "Usar pasos para abordar un conflicto.", "Promover reparaciones en lugar de solo sanciones."], "sections": [{"title": "La idea central", "text": "Un conflicto es un desacuerdo que puede resolverse sin violencia, escuchando a todas las partes. La sanción sola cierra el episodio; la reparación enseña."}, {"title": "Pasos para abordarlo", "items": ["Calmar primero: Separar y esperar a que bajen las emociones antes de hablar.", "Escuchar a cada parte: Cada uno cuenta qué pasó y cómo se sintió, sin interrupciones.", "Buscar una reparación: Acordar qué se puede hacer para reparar el daño y evitar que se repita."]}, {"title": "En el aula", "text": "Dos chicos se pelean por la pelota y uno empuja al otro. La docente los separa, espera unos minutos y escucha a cada uno por turno. Acuerdan una forma de turnarse y el que empujó propone pedir disculpas y ayudar a ordenar los materiales."}, {"title": "Paso a paso", "items": ["Intervení temprano, antes de que escale.", "Esperá a que bajen las emociones.", "Escuchá a cada parte por turno, sin juzgar.", "Acordá una reparación y un compromiso para el futuro."]}, {"title": "Cuidado con…", "items": ["Buscar culpables sin escuchar.", "Resolver el conflicto por los chicos sin que participen.", "Ignorar los conflictos pequeños hasta que escalan."]}], "practice": "Rueda de la reparación: Que el grupo piense formas de reparar en lugar de solo castigar. La consigna completa está en la guía de la lección."} },
  'ga-2-2': { video: { src: m118, poster: m119, title: "Participar y cuidarnos", duration: "1 min 29 s", objective: "Promover la participación del grupo en decisiones cotidianas para fortalecer la responsabilidad.", reflection: "¿Qué decisión del aula podrías compartir con tu grupo este mes?" }, guide: { label: "Guía: Participación y cuidado colectivo.pdf", href: m120 }, reading: {"type": "guide", "keyIdea": "Cuando el grupo participa en decisiones reales, como organizar el aula, elegir un proyecto o revisar un acuerdo, crece la responsabilidad y el cuidado mutuo. Participar también se aprende.", "objectives": ["Identificar decisiones que el grupo puede tomar.", "Organizar formas de participación como asambleas o roles.", "Fortalecer el cuidado mutuo."], "sections": [{"title": "La idea central", "text": "Participar en decisiones reales fortalece la responsabilidad y el cuidado del grupo. No se trata de votar todo, sino de compartir decisiones que importan."}, {"title": "Formas de participar", "items": ["Asamblea breve: Un momento semanal para plantear problemas y propuestas.", "Roles rotativos: Encargados de materiales, del tiempo, de dar la bienvenida.", "Proyectos de cuidado: Cuidar el aula, recibir a los nuevos, ayudar a otro grado."]}, {"title": "En el aula", "text": "Los viernes, el curso hace una asamblea de quince minutos. Esta semana el tema es el ruido en la clase de taller: proponen ideas y votan dos. Al viernes siguiente revisan si funcionaron y ajustan."}, {"title": "Paso a paso", "items": ["Elegí decisiones reales que el grupo pueda tomar.", "Organizá un momento fijo y breve para decidir.", "Rotá roles para que todos participen.", "Revisen juntos si las decisiones funcionaron."]}, {"title": "Cuidado con…", "items": ["Consultar al grupo y no tener en cuenta lo que dice.", "Que siempre participen los mismos.", "Convertir la asamblea en un momento de quejas sin propuestas."]}], "practice": "Asamblea de quince minutos: Dar al grupo un espacio regular para proponer y decidir sobre la vida del aula. La consigna completa está en la guía de la lección."} },
  'ga-3-1': { video: { src: m121, poster: m122, title: "Rutinas que dan autonomía", duration: "1 min 30 s", objective: "Diseñar rutinas visibles que ayuden al grupo a gestionar materiales, tiempos y transiciones.", reflection: "¿Qué transición de tu clase podría tener un cartel con pasos?" }, guide: { label: "Guía: Rutinas que dan autonomía.pdf", href: m123 }, reading: {"type": "guide", "keyIdea": "Las rutinas visibles reducen la incertidumbre: cuando el grupo sabe qué hacer, no depende de que el docente lo indique todo el tiempo. Eso libera tiempo para enseñar y acompañar.", "objectives": ["Identificar momentos que necesitan rutinas.", "Hacer las rutinas visibles con apoyos gráficos.", "Enseñar las rutinas paso a paso."], "sections": [{"title": "La idea central", "text": "Una rutina visible anticipa los pasos y permite que el grupo actúe sin depender del docente. La autonomía se enseña: primero con mucho apoyo y después con menos."}, {"title": "Cómo hacerlas visibles", "items": ["Apoyos gráficos: Carteles con pasos y dibujos, a la vista de todos.", "Tiempos visibles: Un reloj o una cuenta regresiva para saber cuánto queda.", "Enseñarlas: Modelar, practicar y recordar hasta que salgan solas."]}, {"title": "En el aula", "text": "En primer grado, la docente pega un cartel con tres dibujos: guardar, lavar las manos y sentarse. Antes de la merienda, solo señala el cartel y el grupo sigue los pasos. En pocas semanas, los chicos se recuerdan entre ellos qué viene después."}, {"title": "Paso a paso", "items": ["Elegí el momento que más tiempo te hace perder.", "Definí tres o cuatro pasos claros.", "Hacé un cartel con palabras y dibujos.", "Practicá la rutina varias veces y reconocé cuando sale bien."]}, {"title": "Cuidado con…", "items": ["Explicar la rutina una vez y esperar que funcione.", "Hacer carteles con demasiado texto.", "Cambiar los pasos sin avisar."]}], "practice": "Mi rutina en tres pasos: Construir con el grupo una rutina visible para un momento que se repite. La consigna completa está en la guía de la lección."} },
  'ga-3-2': { video: { src: m124, poster: m125, title: "Revisar los acuerdos", duration: "1 min 29 s", objective: "Revisar los acuerdos de convivencia a partir de situaciones concretas.", reflection: "¿Qué acuerdo de tu grupo necesita una revisión?" }, guide: { label: "Guía: Revisar acuerdos con el grupo.pdf", href: m126 }, reading: {"type": "guide", "keyIdea": "Los acuerdos funcionan cuando se entienden, se observan y se revisan. Volver sobre ellos con situaciones reales permite ajustarlos y que el grupo los sienta propios.", "objectives": ["Revisar periódicamente los acuerdos con el grupo.", "Usar situaciones concretas para analizar su cumplimiento.", "Ajustar acuerdos que no funcionan."], "sections": [{"title": "La idea central", "text": "Los acuerdos se sostienen cuando se revisan con situaciones concretas. Revisar no es retar: es pensar juntos qué funciona y qué no."}, {"title": "Cómo revisarlos", "items": ["Momentos fijos: Una revisión breve cada mes o después de una situación importante.", "Situaciones concretas: Analizar un hecho real, sin nombres, a la luz de los acuerdos.", "Ajustes: Cambiar o sumar un acuerdo si el grupo lo necesita."]}, {"title": "En el aula", "text": "Después de una semana con muchos celulares en clase, el profesor propone revisar los acuerdos. El grupo analiza la situación sin señalar a nadie y reconoce que el acuerdo era poco claro. Lo reescriben juntos: el celular se usa solo cuando la actividad lo pide."}, {"title": "Paso a paso", "items": ["Fijá un momento regular para revisar los acuerdos.", "Elegí una situación concreta, sin nombres.", "Preguntá: ¿qué acuerdo se relaciona? ¿Funcionó?", "Ajusten el acuerdo si hace falta y registren el cambio."]}, {"title": "Cuidado con…", "items": ["Revisar los acuerdos solo cuando hay un problema grave.", "Usar la revisión para señalar culpables.", "Agregar acuerdos sin quitar los que no sirven."]}], "practice": "Semáforo de acuerdos: Evaluar con el grupo qué acuerdos funcionan y cuáles hay que ajustar. La consigna completa está en la guía de la lección."} },
  '1-1': { guide: { label: "Guía: La transformación digital en la educación.pdf", href: m127 }, reading: {"type": "guide", "keyIdea": "La transformación digital en la escuela no consiste en sumar dispositivos: implica revisar prácticas, tiempos, vínculos y decisiones pedagógicas para ampliar las oportunidades de aprender.", "objectives": ["Distinguir incorporar tecnología y transformar prácticas.", "Reconocer oportunidades y riesgos de lo digital en la escuela.", "Partir de una necesidad pedagógica al integrar tecnología."], "sections": [{"title": "La idea central", "text": "Transformar no es sumar pantallas: es usar lo digital para enseñar y aprender de otra manera. La pregunta no es qué herramienta usar, sino qué problema de enseñanza queremos resolver."}, {"title": "Tres preguntas antes de incorporar tecnología", "items": ["¿Para qué?: Qué aprendizaje se busca y qué problema ayuda a resolver la herramienta.", "¿Para quiénes?: Si todos pueden acceder y participar, con o sin conexión en casa.", "¿Qué cambia?: Qué práctica se transforma: colaboración, producción, acceso a fuentes, devolución."]}, {"title": "En el aula", "text": "Un profesor pasaba sus clases dictando apuntes. Ahora comparte un documento con fuentes y usa la clase para que los grupos las analicen y comparen. La tecnología no reemplazó la clase: cambió lo que se hace en ella."}, {"title": "Paso a paso", "items": ["Identificá un problema de enseñanza concreto.", "Pensá si una herramienta digital ayuda a resolverlo.", "Revisá que todo el grupo pueda acceder.", "Observá qué cambió en el aprendizaje y ajustá."]}, {"title": "Cuidado con…", "items": ["Usar tecnología para hacer lo mismo de siempre.", "Elegir la herramienta antes que el propósito.", "Suponer que todos tienen conexión y dispositivos."]}], "practice": "Antes y después de lo digital: Reflexionar sobre cómo una herramienta digital puede transformar una práctica concreta. La consigna completa está en la guía de la lección."} },
  'hd-2-1': { video: { src: m128, poster: m129, title: "Documentos compartidos", duration: "1 min 32 s", objective: "Usar documentos compartidos para producir en equipo con roles, acuerdos y devoluciones.", reflection: "¿Qué producción grupal podría hacerse en un documento compartido con roles?" }, guide: { label: "Guía: Documentos compartidos con propósito.pdf", href: m130 }, reading: {"type": "guide", "keyIdea": "Un documento compartido permite que varias personas escriban, comenten y revisen la misma producción. Funciona cuando hay una meta común, roles claros y acuerdos sobre cómo comentar y editar.", "objectives": ["Organizar la escritura colaborativa con roles.", "Usar comentarios para dar devoluciones.", "Revisar el historial para ver el aporte de cada uno."], "sections": [{"title": "La idea central", "text": "Un documento compartido funciona con una meta común, roles claros y acuerdos de edición. Colaborar no es repartir partes: es construir juntos y revisarse."}, {"title": "Cómo organizarlo", "items": ["Una meta compartida: Todos saben qué producto tienen que lograr y para quién.", "Roles rotativos: Redactor, revisor, buscador de fuentes, editor final.", "Comentar antes de borrar: Sugerir con comentarios y no borrar lo que escribió otro."]}, {"title": "En el aula", "text": "Los grupos escriben una noticia sobre un hecho de la escuela en un documento compartido. Cada integrante tiene un rol, y los cambios se sugieren con comentarios. La profesora mira el historial de versiones para ver cómo aportó cada uno y deja una devolución."}, {"title": "Paso a paso", "items": ["Definí la meta y el destinatario del documento.", "Asigná roles y hacé que roten.", "Acordá reglas: comentar antes de borrar.", "Revisá el historial y dejá devoluciones con comentarios."]}, {"title": "Cuidado con…", "items": ["Dividir el trabajo en partes que nunca se integran.", "No acordar cómo editar lo que escribió otro.", "Evaluar solo el producto sin mirar el proceso."]}], "practice": "Noticia en equipo: Escribir en equipo un texto en un documento compartido, con roles y comentarios. La consigna completa está en la guía de la lección."} },
  'hd-2-2': { video: { src: m131, poster: m132, title: "Tableros para organizar ideas", duration: "1 min 34 s", objective: "Usar tableros digitales para reunir, organizar y relacionar aportes del grupo.", reflection: "¿En qué momento de una unidad podría servirte un tablero para organizar ideas?" }, guide: { label: "Guía: Tableros para organizar ideas.pdf", href: m133 }, reading: {"type": "guide", "keyIdea": "Un tablero digital reúne aportes en forma de notas, imágenes o preguntas en un espacio común. Su valor no está en juntar ideas, sino en organizarlas y relacionarlas para pensar mejor.", "objectives": ["Elegir usos pedagógicos del tablero.", "Organizar los aportes en columnas o categorías.", "Usar el tablero para sintetizar."], "sections": [{"title": "La idea central", "text": "Un tablero sirve cuando las ideas se organizan y se relacionan, no solo cuando se juntan. La herramienta junta; el pensamiento lo pone la consigna."}, {"title": "Usos con sentido", "items": ["Recuperar ideas previas: Cada uno escribe qué sabe o qué se pregunta sobre un tema.", "Clasificar: Ordenar aportes en columnas: causas, consecuencias, ejemplos.", "Relacionar: Conectar ideas y armar entre todos un esquema o una conclusión."]}, {"title": "En el aula", "text": "Al empezar el tema de los animales, cada chico publica una nota con algo que sabe. Entre todos los ordenan en tres columnas: cómo se alimentan, cómo se desplazan y dónde viven. Al terminar la unidad vuelven al tablero, corrigen lo que no era cierto y agregan lo nuevo."}, {"title": "Paso a paso", "items": ["Pensá qué querés que el grupo haga con las ideas.", "Prepará columnas o categorías en el tablero.", "Pedí aportes breves, de una idea por nota.", "Cerrá con una síntesis que relacione los aportes."]}, {"title": "Cuidado con…", "items": ["Pedir aportes sin consigna ni organización.", "Dejar el tablero sin volver a él.", "Permitir publicaciones anónimas sin acuerdos de convivencia."]}], "practice": "Tablero de ida y vuelta: Usar un tablero para recuperar ideas previas al inicio y revisarlas al final de una unidad. La consigna completa está en la guía de la lección."} },
  'hd-3-1': { video: { src: m134, poster: m135, title: "Contenidos breves y legibles", duration: "1 min 28 s", objective: "Crear recursos digitales claros que combinen jerarquía, síntesis y ejemplos.", reflection: "¿Qué recurso tuyo podría ganar claridad si lo sintetizás?" }, guide: { label: "Guía: Contenidos breves y legibles.pdf", href: m136 }, reading: {"type": "guide", "keyIdea": "Un recurso digital claro tiene un objetivo, una jerarquía visual que guía la lectura, textos breves y ejemplos. Menos elementos, mejor elegidos, se comprenden más.", "objectives": ["Partir del objetivo al crear un recurso.", "Organizar el contenido con jerarquía visual.", "Sintetizar sin perder precisión."], "sections": [{"title": "La idea central", "text": "Un buen recurso tiene un objetivo, una jerarquía clara y solo lo necesario. Si todo está resaltado, nada está resaltado."}, {"title": "Claves de diseño", "items": ["Una idea por pantalla: Cada diapositiva o sección responde a una sola idea.", "Jerarquía visual: Título, idea principal y detalle, con tamaños distintos.", "Un ejemplo: Un ejemplo concreto vale más que tres párrafos de explicación."]}, {"title": "En el aula", "text": "La docente rehace una presentación sobre fracciones. De ocho diapositivas llenas de texto pasa a cinco: cada una con un título, una idea y un dibujo. Los chicos la usan para repasar solos y la entienden sin su explicación."}, {"title": "Paso a paso", "items": ["Escribí el objetivo del recurso en una frase.", "Dividí el contenido en ideas, una por pantalla.", "Usá títulos claros y textos de pocas líneas.", "Sumá un ejemplo concreto por idea."]}, {"title": "Cuidado con…", "items": ["Copiar textos largos del libro en las diapositivas.", "Usar muchos colores y tipografías.", "Agregar imágenes decorativas que no explican nada."]}], "practice": "Una idea por pantalla: Rediseñar un recurso propio para hacerlo breve y legible. La consigna completa está en la guía de la lección."} },
  'hd-3-2': { video: { src: m137, poster: m138, title: "Producciones multimodales", duration: "1 min 31 s", objective: "Proponer producciones que combinen texto, imagen y audio con funciones claras.", reflection: "¿Qué tema de tu área podría mostrarse con una producción multimodal?" }, guide: { label: "Guía: Producciones multimodales.pdf", href: m139 }, reading: {"type": "guide", "keyIdea": "Combinar texto, imagen y audio amplía las formas de expresar lo aprendido, siempre que cada medio cumpla una función. Además, ofrecer subtítulos y descripciones hace que la producción sea accesible para todos.", "objectives": ["Proponer producciones multimodales con propósito.", "Asignar una función a cada medio.", "Incluir criterios de accesibilidad."], "sections": [{"title": "La idea central", "text": "En una producción multimodal, cada medio cumple una función en la comunicación. Lo multimodal no es decorar: es elegir el mejor medio para cada idea."}, {"title": "Una función para cada medio", "items": ["Texto: Para definir, explicar con precisión o dar datos.", "Imagen: Para mostrar, comparar o representar relaciones.", "Audio: Para narrar, entrevistar o dar voz a otros."]}, {"title": "En el aula", "text": "Para cerrar la unidad sobre la Independencia, los grupos hacen un podcast de tres minutos. Incluyen una entrevista imaginaria a un congresal de 1816 y una infografía con la línea de tiempo. Cada producción lleva su transcripción y la infografía tiene una descripción en texto."}, {"title": "Paso a paso", "items": ["Definí qué aprendizaje tiene que mostrar la producción.", "Ofrecé dos o tres formatos posibles.", "Pedí que justifiquen para qué usan cada medio.", "Incluí subtítulos, transcripción o descripción en los criterios."]}, {"title": "Cuidado con…", "items": ["Evaluar más el efecto visual que el contenido.", "Proponer formatos que exigen recursos que no todos tienen.", "Olvidar la accesibilidad de las producciones."]}], "practice": "Mini podcast: Producir un audio breve que explique un tema, con su transcripción. La consigna completa está en la guía de la lección."} },
  'hd-4-1': { video: { src: m140, poster: m141, title: "Evidencias digitales", duration: "1 min 32 s", objective: "Elegir herramientas digitales de evaluación que permitan observar el aprendizaje buscado.", reflection: "¿Qué segunda evidencia podrías sumar a tu próxima evaluación?" }, guide: { label: "Guía: Evidencias digitales de aprendizaje.pdf", href: m142 }, reading: {"type": "guide", "keyIdea": "Una herramienta digital de evaluación es útil cuando permite ver la capacidad que definimos en el objetivo. Combinar distintas evidencias, como un formulario, una grabación o un documento, da una mirada más completa.", "objectives": ["Elegir la evidencia según el objetivo.", "Combinar distintos tipos de evidencias.", "Evitar que la herramienta defina lo que se evalúa."], "sections": [{"title": "La idea central", "text": "La evidencia se elige según el aprendizaje que se quiere observar, no según la herramienta. Combinar evidencias permite ver el aprendizaje desde más de un ángulo."}, {"title": "Qué evidencia para qué", "items": ["Reconocer o recordar: Un formulario breve con preguntas bien pensadas.", "Explicar: Un audio o video corto donde el estudiante explica con sus palabras.", "Producir: Un documento o un portafolio con versiones y reflexiones."]}, {"title": "En el aula", "text": "Para evaluar el tema de energía, el profesor combina tres evidencias. Un formulario de cinco preguntas, un audio de un minuto explicando un ejemplo de la vida cotidiana y un informe de laboratorio. Así ve si sus estudiantes reconocen conceptos, los explican y los aplican."}, {"title": "Paso a paso", "items": ["Escribí qué capacidad querés evaluar.", "Elegí la evidencia que mejor la muestra.", "Recién entonces elegí la herramienta.", "Combiná al menos dos tipos de evidencias."]}, {"title": "Cuidado con…", "items": ["Elegir la herramienta primero y adaptar el objetivo.", "Evaluar todo con formularios de opción múltiple.", "Pedir evidencias que exigen recursos que no todos tienen."]}], "practice": "Tres evidencias para un tema: Diseñar una evaluación que combine evidencias digitales según el objetivo. La consigna completa está en la guía de la lección."} },
  'hd-4-2': { video: { src: m143, poster: m144, title: "Retroalimentación digital", duration: "1 min 33 s", objective: "Dar devoluciones digitales que señalen un logro, una mejora concreta y un próximo paso.", reflection: "¿Qué tarea de tu grupo podría recibir una devolución digital antes de la entrega final?" }, guide: { label: "Guía: Retroalimentación oportuna.pdf", href: m145 }, reading: {"type": "guide", "keyIdea": "Las herramientas digitales permiten devolver más rápido y en el lugar exacto: un comentario en el documento, un audio breve o una marca en una rúbrica. Lo importante es que la devolución sea específica y llegue a tiempo para mejorar.", "objectives": ["Usar comentarios y audios para retroalimentar.", "Escribir devoluciones específicas.", "Dar tiempo para usar la devolución."], "sections": [{"title": "La idea central", "text": "Una buena devolución digital es específica, llega a tiempo y permite mejorar. Lo digital ayuda a devolver antes; el contenido de la devolución sigue siendo lo importante."}, {"title": "Formas de devolver", "items": ["Comentario en el lugar: Señalar en el mismo texto dónde está el logro y dónde mejorar.", "Audio breve: Un minuto de voz puede ser más claro y cercano que un párrafo escrito.", "Rúbrica marcada: Indicar el nivel en un criterio y qué falta para el siguiente."]}, {"title": "En el aula", "text": "La profesora deja comentarios en los borradores del documento compartido. En uno escribe: «Tu inicio atrapa. Para el final, retomá la pregunta del principio». Al día siguiente, los estudiantes tienen veinte minutos para resolver los comentarios."}, {"title": "Paso a paso", "items": ["Revisá borradores, no solo versiones finales.", "Señalá un logro y una mejora en el lugar exacto.", "Usá audios breves cuando el comentario es largo.", "Dá tiempo en clase para resolver los comentarios."]}, {"title": "Cuidado con…", "items": ["Dejar muchos comentarios en todo el texto.", "Devolver solo la nota en la plataforma.", "Retroalimentar cuando ya no se puede mejorar."]}], "practice": "Devolución en borrador: Usar comentarios digitales sobre borradores para mejorar una producción. La consigna completa está en la guía de la lección."} },
  'hd-5-1': { video: { src: m146, poster: m147, title: "Privacidad y ciudadanía digital", duration: "1 min 32 s", objective: "Revisar datos, permisos, edad y condiciones de uso antes de usar una plataforma con estudiantes.", reflection: "¿Qué plataforma que usás pide datos que podrías evitar?" }, guide: { label: "Guía: Privacidad y ciudadanía digital.pdf", href: m148 }, reading: {"type": "guide", "keyIdea": "Antes de usar una plataforma con estudiantes, conviene revisar qué datos pide, qué permisos solicita, para qué edad está pensada y si hay alternativas sin crear cuentas. También es una oportunidad para enseñar a cuidar los propios datos.", "objectives": ["Revisar condiciones de uso y edad mínima.", "Minimizar los datos personales que se comparten.", "Enseñar hábitos de cuidado de la privacidad."], "sections": [{"title": "La idea central", "text": "Antes de usar una plataforma, revisá datos, permisos, edad y alternativas. Cuidar los datos de los estudiantes también es enseñar ciudadanía digital."}, {"title": "Qué revisar", "items": ["Datos personales: Si pide nombre completo, correo o fotos, y si se puede evitar.", "Permisos y edad: Edad mínima de uso y qué permisos pide en el dispositivo.", "Alternativas: Si se puede usar sin cuenta, con un código de grupo o un apodo."]}, {"title": "En el aula", "text": "La docente quiere usar una aplicación de cuestionarios. Revisa las condiciones y ve que permite jugar con un código y un apodo, sin crear cuentas. Aprovecha para conversar con el grupo sobre por qué no conviene usar el nombre completo en internet."}, {"title": "Paso a paso", "items": ["Leé las condiciones de uso y la edad mínima.", "Elegí opciones sin cuenta o con apodos.", "Pedí autorización a las familias cuando corresponda.", "Conversá con el grupo sobre el cuidado de sus datos."]}, {"title": "Cuidado con…", "items": ["Pedir que los estudiantes creen cuentas personales sin revisar condiciones.", "Subir fotos de estudiantes sin autorización.", "Usar datos reales cuando alcanza con un apodo."]}], "practice": "Detectives de la privacidad: Que el grupo aprenda a revisar qué datos pide una aplicación y por qué cuidarlos. La consigna completa está en la guía de la lección."} },
  'hd-5-2': { video: { src: m149, poster: m150, title: "Implementar y ajustar", duration: "1 min 29 s", objective: "Integrar tecnología de forma sostenible: empezar por una necesidad acotada, observar y mejorar.", reflection: "¿Qué prueba pequeña con tecnología podrías hacer este mes?" }, guide: { label: "Guía: Implementar, observar y ajustar.pdf", href: m151 }, reading: {"type": "guide", "keyIdea": "Una integración sostenible empieza chica: una necesidad concreta, una herramienta, un grupo. Después se observa qué pasó con el aprendizaje y se ajusta. Así se construye una práctica que perdura.", "objectives": ["Empezar por una necesidad pedagógica acotada.", "Definir qué observar durante la implementación.", "Ajustar a partir de evidencias."], "sections": [{"title": "La idea central", "text": "Una integración sostenible empieza chica, se observa y se ajusta. Probar en pequeño permite aprender rápido y sin riesgos grandes."}, {"title": "El ciclo de mejora", "items": ["Elegir una necesidad: Un problema concreto: la participación, la devolución, el acceso a fuentes.", "Probar en pequeño: Una herramienta, una secuencia, un grupo.", "Observar y ajustar: Mirar evidencias, preguntar al grupo y decidir qué cambiar."]}, {"title": "En el aula", "text": "Un profesor quiere mejorar la participación en la revisión de ejercicios. Prueba durante dos semanas un formulario breve al inicio de la clase con un solo curso. Ve que participan más, pero que el formulario lleva mucho tiempo, así que lo acorta a tres preguntas."}, {"title": "Paso a paso", "items": ["Elegí una necesidad pedagógica concreta.", "Probá una sola herramienta con un grupo.", "Definí qué vas a observar.", "Ajustá y decidí si ampliar la prueba."]}, {"title": "Cuidado con…", "items": ["Incorporar muchas herramientas al mismo tiempo.", "Implementar sin definir qué observar.", "Abandonar ante el primer problema sin ajustar."]}], "practice": "Plan de prueba en una página: Planificar una prueba acotada de una herramienta digital con un ciclo de mejora. La consigna completa está en la guía de la lección."} },
  'ia-2-1': { video: { src: m152, poster: m153, title: "Privacidad, sesgos y autoría", duration: "1 min 40 s", objective: "Cuidar los datos personales, reconocer sesgos y transparentar el uso de la inteligencia artificial.", reflection: "¿Qué dato que hoy usás en tu trabajo nunca deberías ingresar en una herramienta pública?" }, guide: { label: "Guía: Privacidad, sesgos y autoría.pdf", href: m154 }, reading: {"type": "guide", "keyIdea": "Usar inteligencia artificial con responsabilidad implica tres cuidados: no compartir datos personales, sospechar de los sesgos que pueden tener sus respuestas y contar con honestidad cómo se usó en una producción.", "objectives": ["Identificar qué datos no deben ingresarse en una herramienta pública.", "Reconocer sesgos en las respuestas generadas.", "Transparentar el uso de la inteligencia artificial en un trabajo."], "sections": [{"title": "La idea central", "text": "Usar la inteligencia artificial con responsabilidad es cuidar datos, sospechar de sesgos y contar cómo se usó. Son cuidados que también se enseñan a los estudiantes."}, {"title": "Tres cuidados", "items": ["Privacidad: No ingresar nombres, fotos, notas, diagnósticos ni datos de familias.", "Sesgos: Las respuestas pueden repetir estereotipos: compararlas con otras fuentes y perspectivas.", "Autoría: Contar qué parte hizo la herramienta y qué decisiones tomó cada uno."]}, {"title": "En el aula", "text": "El profesor pide a una herramienta una lista de «científicos importantes» y obtiene casi solo hombres europeos. Lo muestra en clase y pregunta: ¿quiénes faltan y por qué? El grupo investiga científicas argentinas y latinoamericanas y escribe cómo cambió la lista."}, {"title": "Paso a paso", "items": ["Antes de escribir una consigna, quitá todo dato personal.", "Leé las respuestas buscando ausencias y estereotipos.", "Compará con al menos otra fuente.", "Pedí que cada trabajo cuente cómo se usó la herramienta."]}, {"title": "Cuidado con…", "items": ["Pegar listas de estudiantes o informes en una herramienta pública.", "Tomar la respuesta como neutral y objetiva.", "Prohibir sin enseñar a declarar el uso."]}], "practice": "¿Quién falta en la respuesta?: Detectar sesgos en una respuesta generada y completarla con otras fuentes. La consigna completa está en la guía de la lección."} },
  'ia-2-2': { video: { src: m155, poster: m156, title: "Actividades con IA", duration: "1 min 34 s", objective: "Diseñar actividades donde la inteligencia artificial apoye sin reemplazar el pensamiento del estudiante.", reflection: "¿Qué actividad tuya podría usar la inteligencia artificial para revisar, sin reemplazar el pensamiento?" }, guide: { label: "Guía: Actividades con IA en el aula.pdf", href: m157 }, reading: {"type": "guide", "keyIdea": "La inteligencia artificial puede ser un buen apoyo para explorar, comparar, revisar y crear, siempre que la actividad deje el pensamiento en manos del estudiante: él decide, verifica y justifica.", "objectives": ["Distinguir usos que apoyan y usos que reemplazan el pensamiento.", "Diseñar actividades de exploración y revisión.", "Organizar el uso cuando no todos tienen acceso."], "sections": [{"title": "La idea central", "text": "Una buena actividad con IA deja el pensamiento en el estudiante: decide, verifica y justifica. La pregunta clave: ¿qué tiene que pensar el estudiante en esta actividad?"}, {"title": "Usos que suman", "items": ["Explorar: Pedir ideas para empezar una investigación y elegir cuáles seguir, justificando.", "Comparar: Contrastar una respuesta propia con la generada y mejorar la propia.", "Revisar: Encontrar errores en un texto generado y corregirlos con fuentes."]}, {"title": "En el aula", "text": "La docente proyecta un cuento corto generado por una herramienta, con algunos problemas de coherencia. Los chicos, en grupos, marcan qué no tiene sentido y proponen cómo arreglarlo. Al final escriben su propia versión del final del cuento."}, {"title": "Paso a paso", "items": ["Definí qué tiene que pensar el estudiante.", "Elegí si la herramienta ayuda a explorar, comparar o revisar.", "Si no todos tienen acceso, usala vos de forma proyectada.", "Cerrá con una reflexión sobre qué aportó la herramienta."]}, {"title": "Cuidado con…", "items": ["Pedir tareas que la herramienta resuelve sola.", "Exigir uso en casa cuando no todos tienen acceso.", "No conversar sobre qué aportó y qué no."]}], "practice": "Corregir a la máquina: Desarrollar la lectura crítica corrigiendo un texto generado. La consigna completa está en la guía de la lección."} },
  'ia-3-1': { video: { src: m158, poster: m159, title: "Consignas que exigen pensar", duration: "1 min 37 s", objective: "Formular consignas que pidan contrastar, decidir y justificar en lugar de copiar.", reflection: "¿Qué consigna tuya se resolvería copiando, y cómo la transformarías?" }, guide: { label: "Guía: Consignas que exigen pensar.pdf", href: m160 }, reading: {"type": "guide", "keyIdea": "Si una consigna se puede resolver copiando una respuesta generada, hay que reformularla. Las consignas que piden contrastar, decidir, aplicar a un caso local o justificar mantienen el aprendizaje en el estudiante.", "objectives": ["Reconocer consignas que se resuelven copiando.", "Reformular consignas para exigir pensamiento.", "Incluir decisiones y justificaciones."], "sections": [{"title": "La idea central", "text": "Una consigna crítica pide contrastar, decidir y justificar, no solo reproducir. Lo que la herramienta no puede hacer por vos es decidir con criterio propio."}, {"title": "Cómo transformar una consigna", "items": ["Llevarla a lo local: Aplicar el tema a la escuela, el barrio o la experiencia del grupo.", "Pedir contrastar: Comparar dos fuentes o dos respuestas y explicar diferencias.", "Pedir justificar: Elegir una opción y explicar por qué, con argumentos propios."]}, {"title": "En el aula", "text": "En lugar de «Explicá la fotosíntesis», la profesora propone otra consigna. Observen las plantas del patio durante una semana y expliquen, con lo aprendido, por qué algunas crecen más. Pueden usar una herramienta para consultar, pero tienen que contrastar con sus observaciones."}, {"title": "Paso a paso", "items": ["Probá tu consigna en una herramienta: ¿la resuelve sola?", "Sumá un caso local o una observación propia.", "Pedí comparar, elegir o justificar.", "Pedí que cuenten cómo usaron la herramienta."]}, {"title": "Cuidado con…", "items": ["Prohibir la herramienta en lugar de mejorar la consigna.", "Pedir solo definiciones o resúmenes.", "No valorar el proceso de decisión."]}], "practice": "Consigna a prueba de copia: Reformular consignas para que exijan pensamiento propio. La consigna completa está en la guía de la lección."} },
  'ia-3-2': { video: { src: m161, poster: m162, title: "Evaluar procesos con IA", duration: "1 min 33 s", objective: "Evaluar decisiones, fuentes, revisiones y transparencia además del producto final.", reflection: "¿Qué criterio de proceso podrías sumar a tu próxima evaluación?" }, guide: { label: "Guía: Evaluar procesos asistidos por IA.pdf", href: m163 }, reading: {"type": "guide", "keyIdea": "Cuando una producción se hizo con ayuda de inteligencia artificial, el producto final no alcanza para saber qué se aprendió. Hay que mirar el proceso: qué se pidió, qué se verificó, qué se cambió y por qué.", "objectives": ["Definir criterios que valoren el proceso.", "Pedir registros del uso de la herramienta.", "Valorar la verificación y la transparencia."], "sections": [{"title": "La idea central", "text": "Evaluar con IA es mirar el proceso: fuentes, decisiones, revisiones y transparencia. Hacer visible el proceso es la mejor forma de valorar lo aprendido."}, {"title": "Qué mirar en el proceso", "items": ["Trazabilidad: Qué se pidió, qué respondió la herramienta y qué se hizo con eso.", "Verificación: Qué datos se contrastaron y con qué fuentes.", "Transparencia: Una declaración clara de cómo se usó la herramienta."]}, {"title": "En el aula", "text": "Junto con su informe, cada estudiante entrega una bitácora breve. Ahí cuenta qué le pidió a la herramienta, qué datos verificó en el libro y qué cambió del texto generado. La rúbrica valora el informe y también la calidad de esa bitácora."}, {"title": "Paso a paso", "items": ["Sumá un criterio de proceso a tu rúbrica.", "Pedí una bitácora breve del uso de la herramienta.", "Valorá qué se verificó y con qué fuentes.", "Conversá con algunos estudiantes sobre sus decisiones."]}, {"title": "Cuidado con…", "items": ["Evaluar solo el producto final.", "Usar detectores de IA como prueba definitiva.", "Sancionar el uso declarado en lugar de valorarlo."]}], "practice": "Bitácora de uso: Hacer visible el proceso de una producción asistida por inteligencia artificial. La consigna completa está en la guía de la lección."} },
  'ra-1-1': { video: { src: m164, poster: m165, title: "Barreras digitales", duration: "1 min 40 s", objective: "Identificar barreras frecuentes en los recursos digitales que usamos en clase.", reflection: "¿Qué recurso de los que usás podría tener alguna de estas barreras?" }, guide: { label: "Guía: Reconocer barreras digitales.pdf", href: m166 }, reading: {"type": "guide", "keyIdea": "Un recurso digital puede dejar afuera sin que nos demos cuenta: colores con poco contraste, información solo visual, navegación confusa o archivos que no se pueden abrir. Reconocer estas barreras es el primer paso para evitarlas.", "objectives": ["Reconocer barreras digitales frecuentes.", "Revisar un recurso imaginando distintas personas.", "Priorizar las barreras más importantes."], "sections": [{"title": "La idea central", "text": "Una barrera digital aparece cuando el recurso no contempla distintas formas de ver, oír, leer o usar. La barrera no está en la persona, sino en cómo se diseñó el recurso."}, {"title": "Barreras frecuentes", "items": ["Poco contraste: Textos claros sobre fondos claros, o colores que se confunden.", "Solo imagen: Información que solo está en una imagen o en un color, sin texto.", "Formatos cerrados: Archivos pesados, escaneados o que solo abren con un programa pago."]}, {"title": "En el aula", "text": "Un profesor comparte un afiche con la consigna escrita en amarillo sobre fondo blanco. Varios estudiantes no logran leerla en el celular, y uno que usa lector de pantalla no puede acceder porque es una imagen. La rehace como texto, con buen contraste, y la imagen pasa a ser un complemento."}, {"title": "Paso a paso", "items": ["Mirá tu recurso en un celular, con poco brillo.", "Preguntate si toda la información está también en texto.", "Revisá que el formato se abra en cualquier dispositivo.", "Corregí primero lo que impide acceder al contenido."]}, {"title": "Cuidado con…", "items": ["Pensar la accesibilidad solo cuando hay un estudiante con discapacidad.", "Usar el color como única forma de dar información.", "Compartir consignas como fotos de una hoja."]}], "practice": "Revisión en tres miradas: Detectar barreras en un recurso digital propio. La consigna completa está en la guía de la lección."} },
  'ra-1-2': { video: { src: m167, poster: m168, title: "Estructura y lenguaje claro", duration: "1 min 33 s", objective: "Organizar los recursos con títulos jerárquicos, instrucciones directas y párrafos breves.", reflection: "¿Qué consigna tuya podrías reescribir en pasos numerados?" }, guide: { label: "Guía: Estructura y lenguaje claro.pdf", href: m169 }, reading: {"type": "guide", "keyIdea": "Un recurso bien estructurado se recorre con facilidad: títulos que orientan, párrafos breves y consignas directas. El lenguaje claro no simplifica el contenido, simplifica el camino para llegar a él.", "objectives": ["Usar títulos que organicen el contenido.", "Escribir consignas claras y directas.", "Dividir la información en partes breves."], "sections": [{"title": "La idea central", "text": "Títulos que orientan, párrafos breves y consignas directas hacen más fácil comprender. Lenguaje claro no es lenguaje pobre: es precisión sin obstáculos."}, {"title": "Claves para escribir claro", "items": ["Títulos jerárquicos: Un título por sección, que diga de qué trata.", "Párrafos breves: Una idea por párrafo, oraciones de no más de dos líneas.", "Consignas en pasos: Verbos al inicio y pasos numerados: «Leé, subrayá, respondé»."]}, {"title": "En el aula", "text": "La consigna original decía, en un solo párrafo, todo lo que había que hacer con el cuento. La docente la reescribe en tres pasos numerados: leé el cuento, subrayá a los personajes, escribí qué quiere cada uno. Ese día casi nadie pregunta qué hay que hacer."}, {"title": "Paso a paso", "items": ["Separá tu recurso en secciones con títulos.", "Escribí una idea por párrafo.", "Convertí las consignas en pasos con verbos al inicio.", "Pedí a alguien que lo lea y te diga qué entendió."]}, {"title": "Cuidado con…", "items": ["Poner todas las instrucciones en un solo párrafo.", "Usar negritas o mayúsculas en lugar de títulos.", "Usar palabras técnicas sin explicarlas."]}], "practice": "Consigna en tres pasos: Reescribir una consigna con lenguaje claro y estructura en pasos. La consigna completa está en la guía de la lección."} },
  'ra-2-1': { video: { src: m170, poster: m171, title: "Imágenes con propósito", duration: "1 min 34 s", objective: "Usar imágenes que aporten información y describirlas con texto alternativo.", reflection: "¿Qué imagen de tus materiales necesitaría un texto alternativo?" }, guide: { label: "Guía: Imágenes con propósito.pdf", href: m172 }, reading: {"type": "guide", "keyIdea": "Una imagen educativa tiene un propósito: mostrar, explicar o ejemplificar. El texto alternativo comunica ese propósito a quien no puede verla, por ejemplo una persona que usa lector de pantalla.", "objectives": ["Distinguir imágenes informativas y decorativas.", "Escribir textos alternativos útiles.", "No depender solo de la imagen para comunicar."], "sections": [{"title": "La idea central", "text": "El texto alternativo comunica la información o la función que la imagen tiene en el recurso. No se describe todo lo que se ve, sino lo que importa para entender."}, {"title": "Cómo describir una imagen", "items": ["Preguntá para qué está: ¿Qué información aporta en este recurso?", "Describí lo esencial: Una o dos oraciones con lo que importa, sin empezar con «imagen de».", "Decorativas, vacías: Si la imagen solo decora, se marca como decorativa."]}, {"title": "En el aula", "text": "En una presentación hay un mapa de lluvias de la provincia. Un texto alternativo poco útil sería «mapa». Uno útil: «Las lluvias son mayores en el oeste, en la zona de las yungas, y disminuyen hacia el este». Así, quien no ve el mapa recibe la misma información clave."}, {"title": "Paso a paso", "items": ["Revisá cada imagen de tu recurso.", "Decidí si es informativa o decorativa.", "Escribí en una o dos oraciones lo que comunica.", "Agregalo en el campo de texto alternativo de la herramienta."]}, {"title": "Cuidado con…", "items": ["Escribir «imagen» o el nombre del archivo como descripción.", "Describir detalles que no importan para el aprendizaje.", "Poner texto importante solo dentro de una imagen."]}], "practice": "Describir sin ver: Practicar la descripción de imágenes según su propósito. La consigna completa está en la guía de la lección."} },
  'ra-2-2': { video: { src: m173, poster: m174, title: "Videos accesibles", duration: "1 min 31 s", objective: "Asegurar que los videos tengan subtítulos, transcripción y audio comprensible.", reflection: "¿Qué video de los que usás necesita subtítulos revisados?" }, guide: { label: "Guía: Videos accesibles.pdf", href: m175 }, reading: {"type": "guide", "keyIdea": "Un video es accesible cuando se puede entender sin sonido y sin imagen: los subtítulos representan lo que se dice, la transcripción ofrece el contenido en texto, y el audio se escucha con claridad.", "objectives": ["Reconocer las condiciones de un video accesible.", "Revisar y corregir subtítulos automáticos.", "Ofrecer una transcripción del contenido."], "sections": [{"title": "La idea central", "text": "Un video accesible se entiende con subtítulos, con transcripción y con un audio claro. Lo que se hace para algunos termina sirviendo a todos."}, {"title": "Tres condiciones", "items": ["Subtítulos revisados: Los automáticos ayudan, pero hay que corregir nombres y términos técnicos.", "Transcripción: El contenido del audio en texto, para leer o buscar.", "Audio claro: Sin música de fondo fuerte y hablando a un ritmo pausado."]}, {"title": "En el aula", "text": "La profesora graba una explicación corta y usa subtítulos automáticos. Al revisarlos, encuentra que «estequiometría» salió escrito de tres formas distintas, y lo corrige. Además comparte la transcripción, que varios estudiantes usan para estudiar."}, {"title": "Paso a paso", "items": ["Grabá en un lugar silencioso y hablá pausado.", "Activá subtítulos automáticos y revisalos.", "Corregí nombres propios y términos técnicos.", "Compartí la transcripción junto al video."]}, {"title": "Cuidado con…", "items": ["Confiar en los subtítulos automáticos sin revisar.", "Poner música de fondo que tapa la voz.", "Mostrar texto en pantalla sin leerlo en voz alta."]}], "practice": "Revisión de subtítulos: Revisar y corregir los subtítulos de un video propio o elegido. La consigna completa está en la guía de la lección."} },
  'ra-3-1': { video: { src: m176, poster: m177, title: "Documentos navegables", duration: "1 min 35 s", objective: "Crear documentos con estilos de título, listas reales y tablas simples.", reflection: "¿Qué documento tuyo podrías reorganizar con estilos de título?" }, guide: { label: "Guía: Documentos navegables.pdf", href: m178 }, reading: {"type": "guide", "keyIdea": "Un documento navegable usa la estructura del procesador de textos: estilos de título, listas automáticas y tablas simples. Así se puede recorrer con un lector de pantalla, saltar entre secciones y adaptar a otros formatos.", "objectives": ["Usar estilos de título en lugar de solo formato visual.", "Crear listas y tablas con las herramientas del programa.", "Exportar a formatos que conserven la estructura."], "sections": [{"title": "La idea central", "text": "Un documento navegable conserva su estructura: títulos, listas y tablas reales. Usar la estructura del programa no lleva más tiempo y sirve para todos."}, {"title": "Cómo estructurarlo", "items": ["Estilos de título: Título 1, Título 2: permiten saltar entre secciones y armar un índice.", "Listas automáticas: Usar el botón de lista, no guiones escritos a mano.", "Tablas simples: Con encabezados y sin celdas combinadas."]}, {"title": "En el aula", "text": "El equipo arma un cuadernillo para cuarto grado. Usan estilos de título para cada unidad, listas automáticas para las consignas y tablas con encabezados. Al exportarlo a PDF, el índice se genera solo y un estudiante con baja visión lo amplía sin perder el orden."}, {"title": "Paso a paso", "items": ["Aplicá estilos de título a cada sección.", "Usá listas automáticas para pasos y opciones.", "Armá tablas simples, con fila de encabezado.", "Exportá a PDF conservando la estructura."]}, {"title": "Cuidado con…", "items": ["Simular títulos con negrita y tamaño grande.", "Usar tablas para ordenar el diseño de la página.", "Escanear documentos en lugar de compartir el archivo original."]}], "practice": "Del documento plano al navegable: Transformar un documento propio en un documento navegable. La consigna completa está en la guía de la lección."} },
  'ra-3-2': { video: { src: m179, poster: m180, title: "Comprobar antes de compartir", duration: "1 min 33 s", objective: "Revisar la accesibilidad combinando herramientas automáticas y una lectura manual.", reflection: "¿Qué paso de esta revisión podrías sumar como hábito antes de compartir?" }, guide: { label: "Guía: Comprobar antes de compartir.pdf", href: m181 }, reading: {"type": "guide", "keyIdea": "Antes de compartir un recurso, conviene revisarlo. Las herramientas automáticas detectan algunos problemas, como contraste o imágenes sin descripción, pero no reemplazan una lectura humana del orden, la claridad y las alternativas.", "objectives": ["Usar comprobadores automáticos de accesibilidad.", "Hacer una revisión manual con una lista breve.", "Probar la navegación con teclado."], "sections": [{"title": "La idea central", "text": "Una buena revisión combina herramientas automáticas con una lectura humana. Las herramientas ayudan, pero el criterio es humano."}, {"title": "La revisión en tres pasos", "items": ["Automática: Usar el comprobador de accesibilidad del programa.", "Manual: Revisar orden, claridad, textos alternativos y contraste con una lista.", "Con teclado: Recorrer el recurso solo con la tecla Tab: ¿se llega a todo?"]}, {"title": "En el aula", "text": "Antes de publicar una guía en el aula virtual, la profesora usa el comprobador del procesador de textos. Le marca dos imágenes sin texto alternativo y una tabla sin encabezado, y las corrige. Después la lee con una lista de cinco preguntas y descubre una consigna confusa que el comprobador no detectó."}, {"title": "Paso a paso", "items": ["Pasá el comprobador automático del programa.", "Revisá con una lista breve de cinco preguntas.", "Probá recorrer el recurso con el teclado.", "Corregí lo encontrado antes de compartir."]}, {"title": "Cuidado con…", "items": ["Confiar solo en el comprobador automático.", "Revisar cuando el recurso ya está publicado.", "Hacer listas de revisión tan largas que nadie las usa."]}], "practice": "Lista de cinco preguntas: Incorporar una revisión breve de accesibilidad antes de compartir recursos. La consigna completa está en la guía de la lección."} },
}

